#ifndef XSOX_H
#define XSOX_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>

typedef int32_t sox_sample_t;

#define SOX_SAMPLE_MAX 2147483647.0
#define SOX_SAMPLE_MIN (-2147483647.0 - 1.0)

typedef enum {
  SOX_ENCODING_UNKNOWN = 0,
  SOX_ENCODING_SIGN2,
  SOX_ENCODING_UNSIGNED,
  SOX_ENCODING_FLOAT,
  SOX_ENCODING_ULAW,
  SOX_ENCODING_ALAW,
  SOX_ENCODING_IMA_ADPCM,
  SOX_ENCODING_MS_ADPCM,
  SOX_ENCODING_GSM,
  SOX_ENCODING_OKI_ADPCM,
  SOX_ENCODING_DPCM,
  SOX_ENCODING_DWVW,
  SOX_ENCODING_HCOM,
  SOX_ENCODING_NONE
} sox_encoding_t;

typedef struct {
  sox_encoding_t encoding;
  unsigned bits;          /* encoded sample size in bits */
  unsigned precision;     /* sample precision in bits */
  int endian;             /* 0=little, 1=big, -1=unspecified */
  int opposite_endian;    /* "swap" flag */
  int reverse_bits;
  int reverse_nibbles;
  double compression;     /* compression factor / quality */
} sox_encodinginfo_t;

typedef struct {
  double rate;
  unsigned channels;
  unsigned precision;
  uint64_t length;        /* total samples per channel * channels; 0 = unknown */
} sox_signalinfo_t;

struct sox_format;
typedef struct sox_format sox_format_t;

typedef struct {
  const char * name;          /* canonical name */
  unsigned flags;
  int  (*startread)(sox_format_t *);
  size_t (*read)(sox_format_t *, sox_sample_t *buf, size_t len);
  int  (*stopread)(sox_format_t *);
  int  (*startwrite)(sox_format_t *);
  size_t (*write)(sox_format_t *, const sox_sample_t *buf, size_t len);
  int  (*stopwrite)(sox_format_t *);
  int  (*seek)(sox_format_t *, uint64_t offset);
  const char * description;
  const char * const * names; /* NULL-terminated list of names incl. name */
  /* table of supported write encodings for soxi/--help-format: */
  const unsigned * write_encodings; /* optional */
} sox_format_handler_t;

#define SOX_FILE_NOSTDIO 1
#define SOX_FILE_DEVICE  2
#define SOX_FILE_PHONY   4

struct sox_format {
  char * filename;
  sox_signalinfo_t signal;
  sox_encodinginfo_t encoding;
  const sox_format_handler_t * handler;
  void * priv;
  char mode;              /* 'r' or 'w' */
  FILE * fp;
  int seekable;
  uint64_t tell_off;      /* data-position accounting (bytes) */
  uint64_t data_start;    /* byte offset where data starts */
  uint64_t data_length;   /* bytes of audio data (written or to read) */
  int clip_count;         /* clips during write */
  int sox_errno;
  char errstr[256];
  char * comment;
  uint64_t olength;       /* output length limit (samples), 0 = none */
  uint64_t volume;        /* unused placeholder */
  double vol;             /* input volume adjustment factor, 0 = none */
  uint64_t io_size;       /* total file size if known */
};

/* ---- globals ---- */
extern const char * g_argv0;
extern int g_verbosity;
extern int g_mode; /* 0=sox, 1=soxi, 2=play, 3=rec */
extern int g_use_random; /* -R */

/* ---- output helpers ---- */
void sox_fail(const char * subsys, const char * fmt, ...);
void sox_warn(const char * subsys, const char * fmt, ...);
void sox_info(const char * subsys, const char * fmt, ...);
void sox_debug(const char * subsys, const char * fmt, ...);
void print_version(void);

/* ---- format registry ---- */
const sox_format_handler_t * sox_find_format(const char * name, int by_extension);
const sox_format_handler_t * sox_detect_format(sox_format_t * ft);
extern const sox_format_handler_t * const sox_format_handlers[];

sox_format_t * sox_open_read(const char * path, const sox_signalinfo_t * signal,
    const sox_encodinginfo_t * encoding, const char * filetype);
sox_format_t * sox_open_write(const char * path, const sox_signalinfo_t * signal,
    const sox_encodinginfo_t * encoding, const char * filetype,
    const sox_format_t * in, int no_clobber_prompt);
int sox_close(sox_format_t * ft);

/* raw io helpers (shared by raw-based formats) */
typedef struct {
  sox_encoding_t encoding;
  unsigned bits;
  int endian; /* 0 little 1 big */
  int reverse_bits, reverse_nibbles;
  uint64_t data_length;  /* bytes, 0 = unknown/to-eof */
  uint64_t data_start;
} raw_io_t;

size_t raw_read(sox_format_t * ft, sox_sample_t * buf, size_t len);
size_t raw_write(sox_format_t * ft, const sox_sample_t * buf, size_t len);
void raw_default_encoding(sox_format_t * ft);

/* encoding conversion helpers */
sox_sample_t sox_read_b_sample(sox_format_t * ft); /* internal */
unsigned sox_search_nibble_table(void); /* placeholder */

/* util */
int sox_parse_time(const char * s, double * seconds); /* hh:mm:ss.frac */
uint64_t sox_parse_position(const char * s, const sox_signalinfo_t * sig, int * is_samples, int * relative);
const char * sox_pretty_size(double size, char * buf); /* e.g. "17.7k" */
const char * sox_pretty_bitrate(double bps, char * buf);

/* clip helpers */
extern int g_clip_count_dummy;

/* effects */
struct effect;
typedef struct effect effect_t;
typedef size_t (*eff_input_fn)(effect_t * e, sox_sample_t * buf, size_t max);

typedef struct {
  const char * name;
  const char * usage;      /* short usage text for --help-effect */
  const char * extra;      /* extra text lines (may be NULL) */
  int (*getopts)(effect_t * e, int argc, char ** argv);
  int (*start)(effect_t * e);
  size_t (*flow)(effect_t * e, const sox_sample_t * ibuf, size_t isamp,
                 sox_sample_t * obuf, size_t omax); /* returns produced; sets e->consumed */
  size_t (*drain)(effect_t * e, sox_sample_t * obuf, size_t omax);
  int (*stop)(effect_t * e);
  unsigned flags;
} sox_effect_handler_t;

struct effect {
  const sox_effect_handler_t * handler;
  char * name;
  int argc;
  char ** argv;
  sox_signalinfo_t in_signal, out_signal;
  void * priv;
  size_t consumed;         /* set by flow: how many input samples consumed */
  uint64_t flow_count;
  uint64_t clips;
  eff_input_fn input;      /* pull input */
  /* internal input buffering */
  sox_sample_t * rbuf;     /* residual buffer */
  size_t rlen, rcap;
  int in_eof;
  uint64_t total_in, total_out;
};

const sox_effect_handler_t * sox_find_effect(const char * name);
effect_t * sox_create_effect(const sox_effect_handler_t * h);
void sox_delete_effect(effect_t * e);

/* encoding conversion helpers used by formats */
void init_ulaw_tables(void);
extern int16_t sox_ulaw_decode[256];
extern uint8_t sox_ulaw_encode[16384];
int16_t sox_alaw_decode_byte(uint8_t);
uint8_t sox_alaw_encode_sample(sox_sample_t s);
sox_sample_t sox_ulaw_decode_byte(uint8_t b);
uint8_t sox_ulaw_encode_sample(sox_sample_t s);

/* misc math */
double sox_effective_vol(const char * s, int * type); /* parse gain */

#endif

/* xsox - a clean-room reimplementation of the SoX v14.4.2 command line tool */
#include "xsox.h"
#include "texts.h"
#include <stdarg.h>
#include <ctype.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>

const char * g_argv0 = "sox";
int g_verbosity = 2;
int g_mode = 0;
int g_use_random = 1; /* 1 = random seed (default), 0 = fixed (-R) */

static int show_progress = 0;   /* -S */
static int no_dither = 0;       /* -D */
static int no_clobber = 0;
static int repeatability = 0;
static int combine_method = 0;  /* 0 concatenate, 1 mix, 2 mix-power, 3 merge, 4 multiply, 5 sequence */
static int guard = 0;           /* -G */
static int do_norm = 0;         /* --norm */
static char effects_filename[512] = "";
static size_t input_buffer_size = 8192;
static size_t buffer_size = 8192;
static int multi_threaded = -1;
static char temp_dir[512] = "";
static int dft_min = 10;
static char plot = 0;
static char replay_gain[16] = "";
static int input_count = 0;

static void vx(const char * level, const char * subsys, const char * fmt, va_list ap)
{
  fprintf(stderr, "%s %s %s: ", g_argv0, level, subsys);
  vfprintf(stderr, fmt, ap);
  fputc('\n', stderr);
}

void sox_fail(const char * subsys, const char * fmt, ...)
{ va_list ap; va_start(ap, fmt); if (g_verbosity >= 1) vx("FAIL", subsys, fmt, ap); va_end(ap); }
void sox_warn(const char * subsys, const char * fmt, ...)
{ va_list ap; va_start(ap, fmt); if (g_verbosity >= 2) vx("WARN", subsys, fmt, ap); va_end(ap); }
void sox_info(const char * subsys, const char * fmt, ...)
{ va_list ap; va_start(ap, fmt); if (g_verbosity >= 3) vx("INFO", subsys, fmt, ap); va_end(ap); }
void sox_debug(const char * subsys, const char * fmt, ...)
{ va_list ap; va_start(ap, fmt); if (g_verbosity >= 4) vx("DBUG", subsys, fmt, ap); va_end(ap); }

void print_version(void)
{
  printf("%s:      SoX v14.4.2\n", g_argv0);
}

static void usage(int ret)
{
  print_version();
  fputs(help_text, stdout);
  exit(ret);
}

static void usage_fail(const char * subsys, const char * fmt, ...)
{
  va_list ap;
  va_start(ap, fmt);
  if (g_verbosity >= 1) vx("FAIL", subsys, fmt, ap);
  va_end(ap);
  fputc('\n', stdout);
  usage(1);
}

/* ---------------- option storage for per-file fopts ---------------- */

typedef struct {
  sox_signalinfo_t signal;      /* rate/channels set by -r/-c; 0 = unset */
  sox_encodinginfo_t encoding;  /* set by -e/-b/-N/-X/-L/-B/-x */
  char filetype[32];
  double volume;                /* -v factor, 0 = unset */
  int ignore_length;
  char comment[512];
  int comment_set;
  double compression;           /* -C */
  int compression_set;
  char add_comment[512];
  int add_comment_set;
  char comment_file[512];
  int no_glob;
  /* track which were set */
  int rate_set, channels_set, precision_set;
} fopts_t;

typedef struct {
  char * filename;
  fopts_t opts;
  sox_format_t * ft;
} file_t;

static file_t files[64];
static int nfiles = 0;

static void fopts_init(fopts_t * o)
{
  memset(o, 0, sizeof(*o));
  o->encoding.encoding = SOX_ENCODING_UNKNOWN;
  o->encoding.endian = -1;
}

/* ---------------- encoding name parsing ---------------- */

static const struct { const char * name; sox_encoding_t enc; } enc_names[] = {
  {"signed-integer", SOX_ENCODING_SIGN2},
  {"unsigned-integer", SOX_ENCODING_UNSIGNED},
  {"floating-point", SOX_ENCODING_FLOAT},
  {"mu-law", SOX_ENCODING_ULAW},
  {"a-law", SOX_ENCODING_ALAW},
  {"ima-adpcm", SOX_ENCODING_IMA_ADPCM},
  {"ms-adpcm", SOX_ENCODING_MS_ADPCM},
  {"gsm-full-rate", SOX_ENCODING_GSM},
  {"oki-adpcm", SOX_ENCODING_OKI_ADPCM},
  {"dpcm", SOX_ENCODING_DPCM},
  {"differential", SOX_ENCODING_DPCM},
  {"dwvw", SOX_ENCODING_DWVW},
  {"hcom", SOX_ENCODING_HCOM},
  {NULL, 0}
};

static int parse_encoding(const char * s, sox_encoding_t * e)
{
  int i;
  for (i = 0; enc_names[i].name; i++)
    if (!strcasecmp(s, enc_names[i].name)) { *e = enc_names[i].enc; return 1; }
  return 0;
}

/* ---------------- main parse ---------------- */

int main(int argc, char ** argv)
{
  int i;
  const char * base;
  fopts_t pending;
  int have_pending = 0;
  int seen_filename = 0;

  g_argv0 = argv[0];
  base = strrchr(argv[0], '/');
  base = base ? base + 1 : argv[0];
  if (strstr(base, "soxi")) g_mode = 1;
  else if (!strncmp(base, "play", 4)) g_mode = 2;
  else if (!strncmp(base, "rec", 3)) g_mode = 3;

  if (g_mode == 1) return soxi_main(argc, argv);

  fopts_init(&pending);

  if (argc < 2) {
    if (g_mode == 2 || g_mode == 3) {
      sox_fail("sox", "Sorry, there is no default audio device configured");
      return 2;
    }
    sox_fail("sox", "No input filenames specified");
    fputc('\n', stdout);
    usage(1);
  }

  /* argument walk */
  i = 1;
  /* effects position marker */
  extern int effects_argc; extern char ** effects_argv;
  while (i < argc) {
    char * arg = argv[i];
    if (arg[0] == '-' && arg[1] && strcmp(arg, "-")) {
      /* an option */
      const char * o = arg + 1;
      /* long options */
      if (o[0] == '-') {
        const char * lo = o + 1;
        const char * val = strchr(lo, '=');
        char name[64];
        if (val) { size_t n = val - lo; if (n >= sizeof name) n = sizeof name - 1;
          memcpy(name, lo, n); name[n] = 0; val++; } else { strcpy(name, lo); }
#define LONGOPT(s) (!strcmp(name, s))
#define LONGARG() (val ? (char*)val : (i + 1 < argc ? argv[++i] : (char*)NULL))
        if (LONGOPT("help")) usage(0);
        else if (LONGOPT("version")) { print_version(); return 0; }
        else if (LONGOPT("buffer")) { char * v = LONGARG(); buffer_size = v ? (size_t)atol(v) : 0; }
        else if (LONGOPT("input-buffer")) { char * v = LONGARG(); input_buffer_size = v ? (size_t)atol(v) : 0; }
        else if (LONGOPT("clobber")) no_clobber = 0;
        else if (LONGOPT("no-clobber")) no_clobber = 1;
        else if (LONGOPT("combine")) {
          char * v = LONGARG();
          if (!v) usage_fail("sox", "missing argument to --combine");
          if (!strcmp(v, "concatenate")) combine_method = 0;
          else if (!strcmp(v, "mix")) combine_method = 1;
          else if (!strcmp(v, "mix-power")) combine_method = 2;
          else if (!strcmp(v, "merge")) combine_method = 3;
          else if (!strcmp(v, "multiply")) combine_method = 4;
          else if (!strcmp(v, "sequence")) combine_method = 5;
          else usage_fail("sox", "unknown combine method: %s", v);
        }
        else if (LONGOPT("no-dither")) no_dither = 1;
        else if (LONGOPT("dft-min")) { char * v = LONGARG(); dft_min = v ? atoi(v) : 10; }
        else if (LONGOPT("effects-file")) { char * v = LONGARG(); if (v) strncpy(effects_filename, v, sizeof effects_filename - 1); }
        else if (LONGOPT("guard")) guard = 1;
        else if (LONGOPT("help-effect")) {
          char * v = LONGARG();
          if (!v) usage_fail("sox", "missing argument to --help-effect");
          return show_effect_usage(v);
        }
        else if (LONGOPT("help-format")) {
          char * v = LONGARG();
          if (!v) usage_fail("sox", "missing argument to --help-format");
          return show_format_usage(v);
        }
        else if (LONGOPT("info")) { return soxi_main(argc - i - 1, argv + i + 1); }
        else if (LONGOPT("i")) { return soxi_main(argc - i - 1, argv + i + 1); }
        else if (LONGOPT("multi-threaded")) multi_threaded = 1;
        else if (LONGOPT("single-threaded")) multi_threaded = 0;
        else if (LONGOPT("norm")) { guard = 1; do_norm = 1; }
        else if (LONGOPT("play-rate-arg")) { LONGARG(); }
        else if (LONGOPT("plot")) { char * v = LONGARG(); plot = v ? v[0] : 0; }
        else if (LONGOPT("no-show-progress")) show_progress = 0;
        else if (LONGOPT("show-progress")) show_progress = 1;
        else if (LONGOPT("replay-gain")) { char * v = LONGARG(); if (v) strncpy(replay_gain, v, sizeof replay_gain - 1); }
        else if (LONGOPT("temp")) { char * v = LONGARG(); if (v) strncpy(temp_dir, v, sizeof temp_dir - 1); }
        else if (LONGOPT("type")) { char * v = LONGARG(); if (v) { strncpy(pending.filetype, v, sizeof pending.filetype - 1); have_pending = 1; } }
        else if (LONGOPT("encoding")) {
          char * v = LONGARG();
          if (!v || !parse_encoding(v, &pending.encoding.encoding))
            usage_fail("sox", "invalid encoding: %s", v ? v : "");
          have_pending = 1;
        }
        else if (LONGOPT("bits")) { char * v = LONGARG(); pending.encoding.bits = v ? atoi(v) : 0; have_pending = 1; }
        else if (LONGOPT("reverse-nibbles")) { pending.encoding.reverse_nibbles = 1; have_pending = 1; }
        else if (LONGOPT("reverse-bits")) { pending.encoding.reverse_bits = 1; have_pending = 1; }
        else if (LONGOPT("endian")) {
          char * v = LONGARG();
          if (!v) usage_fail("sox", "missing argument to --endian");
          if (!strcmp(v, "little")) pending.encoding.endian = 0;
          else if (!strcmp(v, "big")) pending.encoding.endian = 1;
          else if (!strcmp(v, "swap")) pending.encoding.opposite_endian = 1;
          else usage_fail("sox", "invalid endian: %s", v);
          have_pending = 1;
        }
        else if (LONGOPT("channels")) { char * v = LONGARG(); pending.signal.channels = v ? atoi(v) : 0; pending.channels_set = 1; have_pending = 1; }
        else if (LONGOPT("rate")) { char * v = LONGARG(); pending.signal.rate = v ? atof(v) : 0; pending.rate_set = 1; have_pending = 1; }
        else if (LONGOPT("compression")) { char * v = LONGARG(); pending.compression = v ? atof(v) : 0; pending.compression_set = 1; have_pending = 1; }
        else if (LONGOPT("volume")) { char * v = LONGARG(); pending.volume = v ? atof(v) : 0; have_pending = 1; }
        else if (LONGOPT("ignore-length")) { pending.ignore_length = 1; have_pending = 1; }
        else if (LONGOPT("add-comment")) { char * v = LONGARG(); if (v) { strncpy(pending.add_comment, v, sizeof pending.add_comment - 1); pending.add_comment_set = 1; } have_pending = 1; }
        else if (LONGOPT("comment")) { char * v = LONGARG(); if (v) { strncpy(pending.comment, v, sizeof pending.comment - 1); pending.comment_set = 1; } have_pending = 1; }
        else if (LONGOPT("comment-file")) { char * v = LONGARG(); if (v) strncpy(pending.comment_file, v, sizeof pending.comment_file - 1); have_pending = 1; }
        else if (LONGOPT("no-glob")) { pending.no_glob = 1; have_pending = 1; }
        else if (LONGOPT("default-device")) {
          /* acts as a filename */
          files[nfiles].filename = strdup("default");
          fopts_init(&files[nfiles].opts);
          strcpy(files[nfiles].opts.filetype, "oss");
          nfiles++;
          seen_filename = 1;
        }
        else if (LONGOPT("null")) {
          files[nfiles].filename = strdup("null");
          fopts_init(&files[nfiles].opts);
          strcpy(files[nfiles].opts.filetype, "null");
          nfiles++;
          seen_filename = 1;
        }
        else if (LONGOPT("sox-pipe")) {
          files[nfiles].filename = strdup("-");
          fopts_init(&files[nfiles].opts);
          strcpy(files[nfiles].opts.filetype, "sox");
          nfiles++;
          seen_filename = 1;
        }
        else {
          usage_fail("sox", "unrecognised option `%s'", arg);
        }
#undef LONGOPT
#undef LONGARG
        i++;
        continue;
      }
      /* short options; -V takes optional digit suffix */
      if (!strcmp(arg, "-h")) usage(0);
      else if (o[0] == 'V') {
        if (o[1]) g_verbosity = atoi(o + 1);
        else g_verbosity++;
        if (g_verbosity > 4) g_verbosity = 4; /* sox caps? verify */
      }
      else if (!strcmp(arg, "-S")) show_progress = 1;
      else if (!strcmp(arg, "-q")) show_progress = 0;
      else if (!strcmp(arg, "-D")) no_dither = 1;
      else if (!strcmp(arg, "-G")) guard = 1;
      else if (!strcmp(arg, "-R")) { g_use_random = 0; repeatability = 1; }
      else if (!strcmp(arg, "-m")) combine_method = 1;
      else if (!strcmp(arg, "-M")) combine_method = 3;
      else if (!strcmp(arg, "-T")) combine_method = 4;
      else if (!strcmp(arg, "-d") || !strcmp(arg, "--default-device")) {
        files[nfiles].filename = strdup("default");
        fopts_init(&files[nfiles].opts);
        strcpy(files[nfiles].opts.filetype, "oss");
        nfiles++;
        seen_filename = 1;
      }
      else if (!strcmp(arg, "-n")) {
        files[nfiles].filename = strdup("null");
        fopts_init(&files[nfiles].opts);
        strcpy(files[nfiles].opts.filetype, "null");
        nfiles++;
        seen_filename = 1;
      }
      else if (!strcmp(arg, "-p")) {
        files[nfiles].filename = strdup("-");
        fopts_init(&files[nfiles].opts);
        strcpy(files[nfiles].opts.filetype, "sox");
        nfiles++;
        seen_filename = 1;
      }
      else if (o[0] == 't' && !o[1]) {
        if (i + 1 >= argc) usage_fail("sox", "missing argument to -t");
        strncpy(pending.filetype, argv[++i], sizeof pending.filetype - 1);
        have_pending = 1;
      }
      else if (o[0] == 'e' && !o[1]) {
        if (i + 1 >= argc) usage_fail("sox", "missing argument to -e");
        if (!parse_encoding(argv[++i], &pending.encoding.encoding))
          usage_fail("sox", "invalid encoding: %s", argv[i]);
        have_pending = 1;
      }
      else if (o[0] == 'b' && !o[1]) {
        if (i + 1 >= argc) usage_fail("sox", "missing argument to -b");
        pending.encoding.bits = atoi(argv[++i]);
        have_pending = 1;
      }
      else if (!strcmp(arg, "-N")) { pending.encoding.reverse_nibbles = 1; have_pending = 1; }
      else if (!strcmp(arg, "-X")) { pending.encoding.reverse_bits = 1; have_pending = 1; }
      else if (!strcmp(arg, "-L")) { pending.encoding.endian = 0; have_pending = 1; }
      else if (!strcmp(arg, "-B")) { pending.encoding.endian = 1; have_pending = 1; }
      else if (!strcmp(arg, "-x")) { pending.encoding.opposite_endian = 1; have_pending = 1; }
      else if (o[0] == 'c' && !o[1]) {
        if (i + 1 >= argc) usage_fail("sox", "missing argument to -c");
        pending.signal.channels = atoi(argv[++i]);
        pending.channels_set = 1;
        have_pending = 1;
      }
      else if (o[0] == 'r' && !o[1]) {
        if (i + 1 >= argc) usage_fail("sox", "missing argument to -r");
        pending.signal.rate = atof(argv[++i]);
        pending.rate_set = 1;
        have_pending = 1;
      }
      else if (o[0] == 'C' && !o[1]) {
        if (i + 1 >= argc) usage_fail("sox", "missing argument to -C");
        pending.compression = atof(argv[++i]);
        pending.compression_set = 1;
        have_pending = 1;
      }
      else if (o[0] == 'v' && !o[1]) {
        if (i + 1 >= argc) usage_fail("sox", "missing argument to -v");
        pending.volume = atof(argv[++i]);
        have_pending = 1;
      }
      else if (!strcmp(arg, "--clobber")) no_clobber = 0;
      else if (!strcmp(arg, "--no-clobber")) no_clobber = 1;
      else if (!strcmp(arg, "--no-dither")) no_dither = 1;
      else if (!strcmp(arg, "--guard")) guard = 1;
      else if (!strcmp(arg, "--norm")) { guard = 1; do_norm = 1; }
      else if (!strcmp(arg, "--ignore-length")) { pending.ignore_length = 1; have_pending = 1; }
      else if (!strcmp(arg, "--multi-threaded")) multi_threaded = 1;
      else if (!strcmp(arg, "--single-threaded")) multi_threaded = 0;
      else if (!strcmp(arg, "--no-glob")) { pending.no_glob = 1; have_pending = 1; }
      else if (arg[1] == '-') {
        usage_fail("sox", "unrecognised option `%s'", arg);
      }
      else {
        usage_fail("sox", "unrecognised option `%s'", arg);
      }
      i++;
      continue;
    }
    /* non-option token */
    if (seen_filename && nfiles >= 2) {
      /* start of effects */
      break;
    }
    files[nfiles].filename = strdup(arg);
    files[nfiles].opts = pending;
    nfiles++;
    fopts_init(&pending);
    have_pending = 0;
    seen_filename = 1;
    i++;
  }

  if (have_pending) {
    usage_fail("sox", "missing filename");
  }

  if (nfiles == 0) {
    sox_fail("sox", "No input filenames specified");
    fputc('\n', stdout);
    usage(1);
  }

  return sox_process(i, argc, argv);
}

/* xsox - format handlers: raw family, wav, au, aiff, null */
#include "xsox.h"
#include <errno.h>
#include <unistd.h>

/* ============ utility: endian io ============ */

static int rd_u8(sox_format_t * ft, unsigned * v)
{ int c = fgetc(ft->fp); if (c == EOF) return 0; *v = (unsigned)c; return 1; }

static int rd_le16(sox_format_t * ft, unsigned * v)
{ unsigned a, b; if (!rd_u8(ft, &a) || !rd_u8(ft, &b)) return 0; *v = a | (b << 8); return 1; }
static int rd_be16(sox_format_t * ft, unsigned * v)
{ unsigned a, b; if (!rd_u8(ft, &a) || !rd_u8(ft, &b)) return 0; *v = (a << 8) | b; return 1; }
static int rd_le24(sox_format_t * ft, uint32_t * v)
{ unsigned a, b, c; if (!rd_u8(ft, &a) || !rd_u8(ft, &b) || !rd_u8(ft, &c)) return 0; *v = a | (b << 8) | ((uint32_t)c << 16); return 1; }
static int rd_be24(sox_format_t * ft, uint32_t * v)
{ unsigned a, b, c; if (!rd_u8(ft, &a) || !rd_u8(ft, &b) || !rd_u8(ft, &c)) return 0; *v = ((uint32_t)a << 16) | (b << 8) | c; return 1; }
static int rd_le32(sox_format_t * ft, uint32_t * v)
{ unsigned a, b, c, d; if (!rd_u8(ft, &a) || !rd_u8(ft, &b) || !rd_u8(ft, &c) || !rd_u8(ft, &d)) return 0;
  *v = a | (b << 8) | ((uint32_t)c << 16) | ((uint32_t)d << 24); return 1; }
static int rd_be32(sox_format_t * ft, uint32_t * v)
{ unsigned a, b, c, d; if (!rd_u8(ft, &a) || !rd_u8(ft, &b) || !rd_u8(ft, &c) || !rd_u8(ft, &d)) return 0;
  *v = ((uint32_t)a << 24) | ((uint32_t)b << 16) | (c << 8) | d; return 1; }

static int wr_u8(sox_format_t * ft, unsigned v)
{ return fputc(v & 0xff, ft->fp) != EOF; }
static int wr_le16(sox_format_t * ft, unsigned v)
{ return wr_u8(ft, v) && wr_u8(ft, v >> 8); }
static int wr_be16(sox_format_t * ft, unsigned v)
{ return wr_u8(ft, v >> 8) && wr_u8(ft, v); }
static int wr_le24(sox_format_t * ft, uint32_t v)
{ return wr_u8(ft, v) && wr_u8(ft, v >> 8) && wr_u8(ft, v >> 16); }
static int wr_be24(sox_format_t * ft, uint32_t v)
{ return wr_u8(ft, v >> 16) && wr_u8(ft, v >> 8) && wr_u8(ft, v); }
static int wr_le32(sox_format_t * ft, uint32_t v)
{ return wr_u8(ft, v) && wr_u8(ft, v >> 8) && wr_u8(ft, v >> 16) && wr_u8(ft, v >> 24); }
static int wr_be32(sox_format_t * ft, uint32_t v)
{ return wr_u8(ft, v >> 24) && wr_u8(ft, v >> 16) && wr_u8(ft, v >> 8) && wr_u8(ft, v); }

static int wr_bytes(sox_format_t * ft, const void * p, size_t n)
{ return fwrite(p, 1, n, ft->fp) == n; }

/* ============ u-law / a-law (G.711) ============ */

static int16_t ulaw_tab[256];
static int16_t alaw_tab[256];
static int tables_ready = 0;

static void init_law_tables(void)
{
  int i;
  if (tables_ready) return;
  tables_ready = 1;
  for (i = 0; i < 256; i++) {
    /* u-law */
    int u = ~i & 0xff;
    int sign = u & 0x80;
    int exp = (u >> 4) & 7;
    int mant = u & 0xf;
    int val = (((mant << 3) + 0x84) << exp) - 0x84;
    ulaw_tab[i] = (int16_t)(sign ? -val : val);
    /* a-law */
    {
      int a = i ^ 0x55;
      int s = a & 0x80;
      int e = (a >> 4) & 7;
      int m = a & 0xf;
      int v;
      if (e == 0) v = (m << 4) + 8;
      else { v = ((m << 4) + 0x108) << (e - 1); }
      alaw_tab[i] = (int16_t)(s ? v : -v);
    }
  }
}

/* encode 16-bit linear to ulaw */
static uint8_t linear_to_ulaw(int sample)
{
  int sign, exponent, mantissa;
  unsigned ulawbyte;
  const int BIAS = 0x84;
  sign = (sample >> 8) & 0x80;
  if (sign) sample = -sample;
  if (sample > 32635) sample = 32635;
  sample += BIAS;
  {
    int exp_mask = 0x4000;
    exponent = 7;
    while (exponent > 0 && !(sample & exp_mask)) { exponent--; exp_mask >>= 1; }
  }
  mantissa = (sample >> (exponent + 3)) & 0x0F;
  ulawbyte = ~(sign | (exponent << 4) | mantissa) & 0xff;
  return (uint8_t)ulawbyte;
}

static uint8_t linear_to_alaw(int sample)
{
  int sign, exponent, mantissa;
  unsigned alawbyte;
  sign = (~sample >> 8) & 0x80;
  if (!sign) sample = -sample - 1;
  if (sample > 32767) sample = 32767;
  if (sample >= 256) {
    int exp_mask = 0x4000;
    exponent = 7;
    while (exponent > 0 && !(sample & exp_mask)) { exponent--; exp_mask >>= 1; }
    mantissa = (sample >> (exponent + 3)) & 0x0F;
    alawbyte = (exponent << 4) | mantissa;
  } else {
    alawbyte = sample >> 4;
  }
  alawbyte ^= sign ^ 0x55;
  return (uint8_t)alawbyte;
}

/* ============ raw io core ============ */

/* Reads raw samples from ft->fp according to ft->encoding into buf (s32).
 * len = number of s32 samples buffer can hold. Returns samples read. */
size_t raw_read(sox_format_t * ft, sox_sample_t * buf, size_t len)
{
  raw_io_t * r = (raw_io_t *)ft->priv;
  size_t done = 0;
  uint64_t bytes_left = r->data_length ? r->data_length - (ft->tell_off - r->data_start) : UINT64_MAX;
  unsigned bytes_per = (r->bits + 7) / 8;

  while (done < len) {
    uint32_t v = 0;
    int ok = 0;
    if (bytes_left == 0) break;
    switch (r->encoding) {
      case SOX_ENCODING_SIGN2:
        switch (r->bits) {
          case 8: { unsigned a; ok = rd_u8(ft, &a); v = (uint32_t)(int32_t)(int8_t)a << 24; break; }
          case 16: { ok = r->endian ? rd_be16(ft, &v) : rd_le16(ft, &v); v = (uint32_t)(int32_t)(int16_t)v << 16; break; }
          case 24: { ok = r->endian ? rd_be24(ft, &v) : rd_le24(ft, &v); v = (v << 8); if (v & 0x80000000u) {} /* sign in bit31 after shift */ break; }
          case 32: { ok = r->endian ? rd_be32(ft, &v) : rd_le32(ft, &v); break; }
          default: break;
        }
        if (ok) { buf[done++] = (sox_sample_t)v; bytes_left -= bytes_per; }
        break;
      case SOX_ENCODING_UNSIGNED:
        switch (r->bits) {
          case 8: { unsigned a; ok = rd_u8(ft, &a); v = ((uint32_t)a ^ 0x80) << 24; break; }
          case 16: { ok = r->endian ? rd_be16(ft, &v) : rd_le16(ft, &v); v = (v ^ 0x8000) << 16; break; }
          case 24: { ok = r->endian ? rd_be24(ft, &v) : rd_le24(ft, &v); v = (v ^ 0x800000) << 8; break; }
          case 32: { ok = r->endian ? rd_be32(ft, &v) : rd_le32(ft, &v); v ^= 0x80000000u; break; }
          default: break;
        }
        if (ok) { buf[done++] = (sox_sample_t)v; bytes_left -= bytes_per; }
        break;
      case SOX_ENCODING_FLOAT:
        if (r->bits == 32) {
          ok = r->endian ? rd_be32(ft, &v) : rd_le32(ft, &v);
          if (ok) { float f; double d; memcpy(&f, &v, 4); d = f;
            d *= (SOX_SAMPLE_MAX + 1.0);
            if (d > SOX_SAMPLE_MAX) { d = SOX_SAMPLE_MAX; ft->clip_count++; }
            else if (d < SOX_SAMPLE_MIN) { d = SOX_SAMPLE_MIN; ft->clip_count++; }
            buf[done++] = (sox_sample_t)d; bytes_left -= 4; }
        } else {
          union { uint64_t u; double d; } cv; uint32_t hi, lo;
          ok = r->endian ? (rd_be32(ft, &hi) && rd_be32(ft, &lo)) : (rd_le32(ft, &lo) && rd_le32(ft, &hi));
          if (ok) { double d; cv.u = ((uint64_t)hi << 32) | lo; d = cv.d;
            d *= (SOX_SAMPLE_MAX + 1.0);
            if (d > SOX_SAMPLE_MAX) { d = SOX_SAMPLE_MAX; ft->clip_count++; }
            else if (d < SOX_SAMPLE_MIN) { d = SOX_SAMPLE_MIN; ft->clip_count++; }
            buf[done++] = (sox_sample_t)d; bytes_left -= 8; }
        }
        break;
      case SOX_ENCODING_ULAW: {
        unsigned a; init_law_tables();
        ok = rd_u8(ft, &a);
        if (ok) { buf[done++] = ((sox_sample_t)ulaw_tab[a]) << 16; bytes_left -= 1; }
        break;
      }
      case SOX_ENCODING_ALAW: {
        unsigned a; init_law_tables();
        ok = rd_u8(ft, &a);
        if (ok) { buf[done++] = ((sox_sample_t)alaw_tab[a]) << 16; bytes_left -= 1; }
        break;
      }
      default:
        return done;
    }
    if (!ok) break;
    ft->tell_off += bytes_per;
  }
  return done;
}

/* clip with count */
static sox_sample_t clip_r(sox_format_t * ft, double v)
{
  if (v > SOX_SAMPLE_MAX) { ft->clip_count++; return (sox_sample_t)SOX_SAMPLE_MAX; }
  if (v < SOX_SAMPLE_MIN) { ft->clip_count++; return (sox_sample_t)SOX_SAMPLE_MIN; }
  return (sox_sample_t)v;
}

size_t raw_write(sox_format_t * ft, const sox_sample_t * buf, size_t len)
{
  raw_io_t * r = (raw_io_t *)ft->priv;
  size_t done = 0;
  unsigned bytes_per = (r->bits + 7) / 8;

  while (done < len) {
    sox_sample_t s = buf[done];
    int ok = 0;
    switch (r->encoding) {
      case SOX_ENCODING_SIGN2:
        switch (r->bits) {
          case 8: { int32_t v = (s + (1 << 23)) >> 24; if (v > 127) { v = 127; ft->clip_count++; } if (v < -128) { v = -128; ft->clip_count++; } ok = wr_u8(ft, (unsigned)(v & 0xff)); break; }
          case 16: { int32_t v = (s + (1 << 15)) >> 16; if (v > 32767) { v = 32767; ft->clip_count++; } if (v < -32768) { v = -32768; ft->clip_count++; } ok = r->endian ? wr_be16(ft, (unsigned)(v & 0xffff)) : wr_le16(ft, (unsigned)(v & 0xffff)); break; }
          case 24: { uint32_t v = ((uint32_t)s >> 8) & 0xffffff; ok = r->endian ? wr_be24(ft, v) : wr_le24(ft, v); break; }
          case 32: ok = r->endian ? wr_be32(ft, (uint32_t)s) : wr_le32(ft, (uint32_t)s); break;
          default: break;
        }
        break;
      case SOX_ENCODING_UNSIGNED:
        switch (r->bits) {
          case 8: { int32_t v = (s + (1 << 23)) >> 24; if (v > 127) { v = 127; ft->clip_count++; } if (v < -128) { v = -128; ft->clip_count++; } ok = wr_u8(ft, (unsigned)((v ^ 0x80) & 0xff)); break; }
          case 16: { int32_t v = (s + (1 << 15)) >> 16; if (v > 32767) { v = 32767; ft->clip_count++; } if (v < -32768) { v = -32768; ft->clip_count++; } ok = r->endian ? wr_be16(ft, (unsigned)((v ^ 0x8000) & 0xffff)) : wr_le16(ft, (unsigned)((v ^ 0x8000) & 0xffff)); break; }
          case 24: { uint32_t v = (((uint32_t)s >> 8) ^ 0x800000) & 0xffffff; ok = r->endian ? wr_be24(ft, v) : wr_le24(ft, v); break; }
          case 32: ok = r->endian ? wr_be32(ft, (uint32_t)s ^ 0x80000000u) : wr_le32(ft, (uint32_t)s ^ 0x80000000u); break;
          default: break;
        }
        break;
      case SOX_ENCODING_FLOAT: {
        double d = s * (1.0 / (SOX_SAMPLE_MAX + 1.0));
        if (r->bits == 32) { float f = (float)d; uint32_t v; memcpy(&v, &f, 4); ok = r->endian ? wr_be32(ft, v) : wr_le32(ft, v); }
        else { union { uint64_t u; double d; } cv; cv.d = d; ok = r->endian ? (wr_be32(ft, (uint32_t)(cv.u >> 32)) && wr_be32(ft, (uint32_t)cv.u)) : (wr_le32(ft, (uint32_t)cv.u) && wr_le32(ft, (uint32_t)(cv.u >> 32))); }
        break;
      }
      case SOX_ENCODING_ULAW: {
        int32_t v = (s + (1 << 15)) >> 16;
        if (v > 32767) { v = 32767; ft->clip_count++; }
        if (v < -32768) { v = -32768; ft->clip_count++; }
        init_law_tables();
        ok = wr_u8(ft, linear_to_ulaw(v));
        break;
      }
      case SOX_ENCODING_ALAW: {
        int32_t v = (s + (1 << 15)) >> 16;
        if (v > 32767) { v = 32767; ft->clip_count++; }
        if (v < -32768) { v = -32768; ft->clip_count++; }
        init_law_tables();
        ok = wr_u8(ft, linear_to_alaw(v));
        break;
      }
      default:
        break;
    }
    if (!ok) break;
    ft->tell_off += bytes_per;
    ft->data_length += bytes_per;
    done++;
  }
  return done;
}

void raw_default_encoding(sox_format_t * ft)
{
  if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN)
    ft->encoding.encoding = SOX_ENCODING_SIGN2;
  if (!ft->encoding.bits)
    ft->encoding.bits = 16;
  if (ft->encoding.endian < 0)
    ft->encoding.endian = 0;
}

/* generic raw start */
static int raw_start_common(sox_format_t * ft, raw_io_t * r)
{
  r->encoding = ft->encoding.encoding;
  r->bits = ft->encoding.bits;
  r->endian = ft->encoding.endian == 1;
  r->reverse_bits = ft->encoding.reverse_bits;
  r->reverse_nibbles = ft->encoding.reverse_nibbles;
  r->data_start = ft->tell_off;
  if (ft->mode == 'r') {
    if (ft->signal.length)
      r->data_length = ft->signal.length * ((r->bits + 7) / 8);
    else
      r->data_length = 0;
  } else {
    r->data_length = 0;
    ft->data_length = 0;
  }
  ft->priv = r;
  return 0;
}

/* ============ raw format handler ============ */

static int raw_startread(sox_format_t * ft)
{
  raw_io_t * r = calloc(1, sizeof *r);
  int rc = raw_start_common(ft, r);
  if (!ft->signal.rate) ft->signal.rate = 8000;
  if (!ft->signal.channels) ft->signal.channels = 1;
  if (!ft->signal.precision) ft->signal.precision = ft->encoding.bits;
  return rc;
}

static int raw_startwrite(sox_format_t * ft)
{
  raw_io_t * r = calloc(1, sizeof *r);
  return raw_start_common(ft, r);
}

static int raw_stop(sox_format_t * ft)
{
  free(ft->priv);
  return 0;
}

/* ============ null format ============ */

static int null_start(sox_format_t * ft)
{
  if (!ft->signal.rate) ft->signal.rate = 44100;
  if (!ft->signal.channels) ft->signal.channels = 1;
  if (!ft->signal.precision) ft->signal.precision = 16;
  if (!ft->encoding.bits) ft->encoding.bits = 16;
  if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN) ft->encoding.encoding = SOX_ENCODING_SIGN2;
  return 0;
}
static size_t null_read(sox_format_t * ft, sox_sample_t * buf, size_t len)
{ (void)ft; (void)buf; (void)len; return 0; }
static size_t null_write(sox_format_t * ft, const sox_sample_t * buf, size_t len)
{ ft->data_length += len * 4; (void)buf; return len; }

