const sox_format_handler_t * sox_find_format(const char * name, int by_extension)
{
  int i, j;
  (void)by_extension;
  for (i = 0; sox_format_handlers[i]; i++)
    for (j = 0; sox_format_handlers[i]->names[j]; j++)
      if (!strcasecmp(name, sox_format_handlers[i]->names[j]))
        return sox_format_handlers[i];
  return NULL;
}

/* ================= open/close ================= */

static sox_format_t * alloc_ft(const char * path)
{
  sox_format_t * ft = calloc(1, sizeof *ft);
  ft->filename = strdup(path);
  ft->encoding.endian = -1;
  ft->vol = 0;
  return ft;
}

static void set_io_size(sox_format_t * ft)
{
  if (ft->fp && ft->seekable) {
    long cur = ftell(ft->fp);
    fseek(ft->fp, 0, SEEK_END);
    ft->io_size = (uint64_t)ftell(ft->fp);
    fseek(ft->fp, cur, SEEK_SET);
  }
}

sox_format_t * sox_open_read(const char * path, const sox_signalinfo_t * signal,
    const sox_encodinginfo_t * encoding, const char * filetype)
{
  sox_format_t * ft = alloc_ft(path);
  ft->mode = 'r';
  if (signal) ft->signal = *signal;
  if (encoding) ft->encoding = *encoding;

  if (!strcmp(path, "-")) {
    ft->fp = stdin;
    ft->seekable = 0;
  } else if (path[0] == '|') {
    ft->fp = popen(path + 1, "r");
    ft->seekable = 0;
    if (!ft->fp) { sox_fail("formats", "can't open input pipe `%s': %s", path, strerror(errno)); free(ft->filename); free(ft); return NULL; }
  } else {
    ft->fp = fopen(path, "rb");
    if (!ft->fp) {
      sox_fail("formats", "can't open input file `%s': %s", path, strerror(errno));
      free(ft->filename); free(ft);
      return NULL;
    }
    ft->seekable = 1;
  }
  set_io_size(ft);

  if (filetype && *filetype) {
    ft->handler = sox_find_format(filetype, 0);
    if (!ft->handler) {
      sox_fail("formats", "no handler for given file type `%s'", filetype);
      if (ft->fp != stdin) fclose(ft->fp);
      free(ft->filename); free(ft);
      return NULL;
    }
  } else {
    ft->handler = sox_detect_format(ft);
    if (!ft->handler) {
      sox_fail("formats", "can't determine type of file `%s'", path);
      if (ft->fp != stdin) fclose(ft->fp);
      free(ft->filename); free(ft);
      return NULL;
    }
  }

  if (ft->handler->startread(ft)) {
    if (ft->sox_errno) sox_fail("formats", "%s", ft->errstr);
    if (ft->fp != stdin) fclose(ft->fp);
    free(ft->filename); free(ft->priv); free(ft);
    return NULL;
  }
  return ft;
}

sox_format_t * sox_open_write(const char * path, const sox_signalinfo_t * signal,
    const sox_encodinginfo_t * encoding, const char * filetype,
    const sox_format_t * in, int no_clobber_prompt)
{
  sox_format_t * ft = alloc_ft(path);
  ft->mode = 'w';
  ft->signal = *signal;
  ft->encoding = *encoding;
  (void)in;

  if (!strcmp(path, "-")) {
    ft->fp = stdout;
    ft->seekable = 0;
  } else {
    if (!no_clobber_prompt && access(path, F_OK) == 0) {
      /* handled by caller */
    }
    ft->fp = fopen(path, "wb");
    if (!ft->fp) {
      sox_fail("formats", "can't open output file `%s': %s", path, strerror(errno));
      free(ft->filename); free(ft);
      return NULL;
    }
    ft->seekable = 1;
  }

  ft->handler = sox_find_format(filetype, 0);
  if (!ft->handler) {
    sox_fail("formats", "no handler for given file type `%s'", filetype);
    if (ft->fp != stdout) fclose(ft->fp);
    free(ft->filename); free(ft);
    return NULL;
  }
  if (ft->handler->startwrite(ft)) {
    if (ft->sox_errno) sox_fail("formats", "%s", ft->errstr);
    if (ft->fp != stdout) fclose(ft->fp);
    free(ft->filename); free(ft->priv); free(ft);
    return NULL;
  }
  return ft;
}

int sox_close(sox_format_t * ft)
{
  int rc = 0;
  if (ft->mode == 'r') {
    if (ft->handler->stopread) rc = ft->handler->stopread(ft);
    if (ft->fp && ft->fp != stdin) fclose(ft->fp);
  } else {
    if (ft->handler->stopwrite) rc = ft->handler->stopwrite(ft);
    if (ft->fp && ft->fp != stdout) fclose(ft->fp);
  }
  free(ft->filename);
  free(ft);
  return rc;
}

/* xsox - WAV (RIFF) format handler */
#include "xsox.h"
#include <errno.h>

typedef struct {
  raw_io_t raw;
  uint64_t data_size;     /* bytes in data chunk */
  uint64_t num_frames;
  unsigned format_tag;
} wav_t;

static int rd_le16f(sox_format_t * ft, unsigned * v)
{ int a = fgetc(ft->fp), b = fgetc(ft->fp); if (b == EOF) return 0; *v = (unsigned)(a | (b << 8)); return 1; }
static int rd_le32f(sox_format_t * ft, uint32_t * v)
{ unsigned a, b; if (!rd_le16f(ft, &a) || !rd_le16f(ft, &b)) return 0; *v = a | ((uint32_t)b << 16); return 1; }
static int rd_be32f(sox_format_t * ft, uint32_t * v)
{ int a = fgetc(ft->fp), b = fgetc(ft->fp), c = fgetc(ft->fp), d = fgetc(ft->fp);
  if (d == EOF) return 0; *v = ((uint32_t)a << 24) | ((uint32_t)b << 16) | ((uint32_t)c << 8) | (uint32_t)d; return 1; }
static int rd_be16f(sox_format_t * ft, unsigned * v)
{ int a = fgetc(ft->fp), b = fgetc(ft->fp); if (b == EOF) return 0; *v = (unsigned)((a << 8) | b); return 1; }
static int wr_le16f(sox_format_t * ft, unsigned v)
{ return fputc(v & 0xff, ft->fp) != EOF && fputc((v >> 8) & 0xff, ft->fp) != EOF; }
static int wr_le32f(sox_format_t * ft, uint32_t v)
{ return wr_le16f(ft, v & 0xffff) && wr_le16f(ft, v >> 16); }
static int wr_str(sox_format_t * ft, const char * s)
{ return fwrite(s, 1, 4, ft->fp) == 4; }

static void wav_fail(sox_format_t * ft, const char * msg)
{
  ft->sox_errno = 1;
  snprintf(ft->errstr, sizeof ft->errstr, "WAV: %s", msg);
}

static int wav_startread(sox_format_t * ft)
{
  char id[4];
  uint32_t riff_size, chunk_size;
  unsigned tag = 0, channels = 0, bits = 0, blockalign = 0;
  uint32_t rate = 0;
  int is_rifx = 0;
  int have_fmt = 0;
  wav_t * w = calloc(1, sizeof *w);

  ft->priv = w;

  if (fread(id, 1, 4, ft->fp) != 4) { wav_fail(ft, "error reading WAV header"); return 1; }
  if (!memcmp(id, "RIFX", 4)) is_rifx = 1;
  else if (memcmp(id, "RIFF", 4)) { wav_fail(ft, "not a WAV file"); return 1; }

  #define RD32(v) (is_rifx ? rd_be32f(ft, v) : rd_le32f(ft, v))
  #define RD16(v) (is_rifx ? rd_be16f(ft, v) : rd_le16f(ft, v))

  if (!RD32(&riff_size)) { wav_fail(ft, "error reading WAV header"); return 1; }
  if (fread(id, 1, 4, ft->fp) != 4 || memcmp(id, "WAVE", 4)) { wav_fail(ft, "not a WAV file"); return 1; }

  /* chunk walk */
  for (;;) {
    uint32_t csize;
    long next;
    if (fread(id, 1, 4, ft->fp) != 4) break;
    if (!RD32(&csize)) break;
    next = ftell(ft->fp) + csize + (csize & 1);
    if (!memcmp(id, "fmt ", 4)) {
      uint32_t dw;
      if (!RD16(&tag)) break;
      if (!RD16(&channels)) break;
      if (!RD32(&rate)) break;
      if (!RD32(&dw)) break;      /* avg bytes per sec */
      if (!RD16(&blockalign)) break;
      if (csize >= 16) { if (!RD16(&bits)) break; }
      if (tag == 0xfffe && csize >= 40) {
        /* extensible: skip cbSize, valid bits, channel mask, read GUID tag */
        unsigned cb; uint32_t valid, mask;
        long pos = ftell(ft->fp);
        if (!RD16(&cb)) break;
        if (!RD32(&valid)) break;
        if (!RD32(&mask)) break;
        {
          unsigned t2;
          if (!RD16(&t2)) break;
          tag = t2; /* GUID first 2 bytes = real tag */
        }
        (void)pos;
      }
      have_fmt = 1;
    } else if (!memcmp(id, "data", 4)) {
      if (!have_fmt) { wav_fail(ft, "missing fmt chunk"); return 1; }
      w->data_size = csize;
      w->raw.data_start = ftell(ft->fp);
      ft->tell_off = w->raw.data_start;
      w->raw.data_length = csize;
      goto found_data;
    } else if (!memcmp(id, "fact", 4)) {
      /* skip */
    }
    if (fseek(ft->fp, next, SEEK_SET)) break;
  }
  wav_fail(ft, "missing data chunk");
  return 1;

found_data:
  /* map tag to encoding */
  switch (tag) {
    case 1: ft->encoding.encoding = bits == 8 ? SOX_ENCODING_UNSIGNED : SOX_ENCODING_SIGN2; break;
    case 3: ft->encoding.encoding = SOX_ENCODING_FLOAT; break;
    case 6: ft->encoding.encoding = SOX_ENCODING_ALAW; bits = 8; break;
    case 7: ft->encoding.encoding = SOX_ENCODING_ULAW; bits = 8; break;
    default:
      snprintf(ft->errstr, sizeof ft->errstr, "WAV: unsupported encoding %u", tag);
      ft->sox_errno = 1;
      return 1;
  }
  w->format_tag = tag;
  ft->encoding.bits = bits;
  ft->encoding.precision = bits;
  if (ft->encoding.encoding == SOX_ENCODING_ULAW) ft->encoding.precision = 14;
  if (ft->encoding.encoding == SOX_ENCODING_ALAW) ft->encoding.precision = 13;
  if (ft->encoding.encoding == SOX_ENCODING_FLOAT) ft->encoding.precision = bits == 64 ? 54 : 25;
  if (ft->encoding.endian < 0) ft->encoding.endian = is_rifx ? 1 : 0;
  if (!ft->signal.rate) ft->signal.rate = rate;
  if (!ft->signal.channels) ft->signal.channels = channels;
  if (!ft->signal.precision) ft->signal.precision = ft->encoding.precision;
  w->num_frames = blockalign ? w->data_size / blockalign : 0;
  ft->signal.length = (uint64_t)w->num_frames * ft->signal.channels;

  w->raw.encoding = ft->encoding.encoding;
  w->raw.bits = ft->encoding.bits;
  w->raw.endian = is_rifx;
  return 0;
}

static size_t wav_read(sox_format_t * ft, sox_sample_t * buf, size_t len)
{
  return raw_read(ft, buf, len);
}

static int wav_stopread(sox_format_t * ft)
{
  free(ft->priv);
  return 0;
}

/* ---------- writing ---------- */

static int wav_startwrite(sox_format_t * ft)
{
  wav_t * w = calloc(1, sizeof *w);
  unsigned tag;
  int extensible = 0, have_fact = 0;
  unsigned bits = ft->encoding.bits;
  unsigned channels = ft->signal.channels;
  unsigned rate = (unsigned)(ft->signal.rate + 0.5);
  unsigned blockalign, avg;

  ft->priv = w;
  if (!bits) bits = 16;

  switch (ft->encoding.encoding) {
    case SOX_ENCODING_SIGN2:
      tag = 1;
      if (bits > 16) extensible = 1;
      break;
    case SOX_ENCODING_UNSIGNED:
      tag = 1; bits = 8;
      break;
    case SOX_ENCODING_FLOAT:
      tag = 3; have_fact = 1;
      break;
    case SOX_ENCODING_ULAW:
      tag = 7; bits = 8; have_fact = 1;
      break;
    case SOX_ENCODING_ALAW:
      tag = 6; bits = 8; have_fact = 1;
      break;
    default:
      tag = 1;
      break;
  }
  if (extensible) have_fact = 1;
  w->format_tag = tag;

  blockalign = channels * ((bits + 7) / 8);
  avg = rate * blockalign;

  wr_str(ft, "RIFF");
  wr_le32f(ft, 0); /* patch later */
  wr_str(ft, "WAVE");
  wr_str(ft, "fmt ");
  if (extensible) {
    wr_le32f(ft, 40);
    wr_le16f(ft, 0xfffe);
    wr_le16f(ft, channels);
    wr_le32f(ft, rate);
    wr_le32f(ft, avg);
    wr_le16f(ft, blockalign);
    wr_le16f(ft, bits);
    wr_le16f(ft, 22);          /* cbSize */
    wr_le16f(ft, bits);        /* valid bits */
    /* channel mask */
    {
      uint32_t mask;
      switch (channels) {
        case 1: mask = 4; break;
        case 2: mask = 3; break;
        case 3: mask = 7; break;
        case 4: mask = 0x33; break;
        case 5: mask = 0x37; break;
        case 6: mask = 0x3f; break;
        case 7: mask = 0x13f; break;
        case 8: mask = 0x63f; break;
        default: mask = 0; break;
      }
      wr_le32f(ft, mask);
    }
    /* GUID */
    wr_le16f(ft, tag);
    {
      static const unsigned char rest[14] = {0x00,0x00,0x00,0x00,0x10,0x00,0x80,0x00,0x00,0xaa,0x00,0x38,0x9b,0x71};
      fwrite(rest, 1, 14, ft->fp);
    }
  } else if (have_fact) {
    wr_le32f(ft, 18);
    wr_le16f(ft, tag);
    wr_le16f(ft, channels);
    wr_le32f(ft, rate);
    wr_le32f(ft, avg);
    wr_le16f(ft, blockalign);
    wr_le16f(ft, bits);
    wr_le16f(ft, 0);           /* cbSize */
  } else {
    wr_le32f(ft, 16);
    wr_le16f(ft, tag);
    wr_le16f(ft, channels);
    wr_le32f(ft, rate);
    wr_le32f(ft, avg);
    wr_le16f(ft, blockalign);
    wr_le16f(ft, bits);
  }
  if (have_fact) {
    wr_str(ft, "fact");
    wr_le32f(ft, 4);
    wr_le32f(ft, 0); /* patch: num frames */
  }
  wr_str(ft, "data");
  wr_le32f(ft, 0); /* patch: data size */

  w->raw.encoding = ft->encoding.encoding == SOX_ENCODING_UNSIGNED ? SOX_ENCODING_UNSIGNED :
                    ft->encoding.encoding;
  w->raw.bits = bits;
  w->raw.endian = 0;
  w->raw.data_start = ftell(ft->fp);
  ft->tell_off = w->raw.data_start;
  ft->data_length = 0;
  w->raw.data_length = 0;
  return 0;
}

static size_t wav_write(sox_format_t * ft, const sox_sample_t * buf, size_t len)
{
  return raw_write(ft, buf, len);
}

static int wav_stopwrite(sox_format_t * ft)
{
  wav_t * w = ft->priv;
  unsigned bytes_per = (w->raw.bits + 7) / 8;
  uint64_t data_bytes = ft->data_length;

  /* pad odd */
  if (data_bytes & 1) {
    fputc(0, ft->fp);
  }
  if (ft->seekable) {
    uint64_t filesize = ftell(ft->fp);
    uint64_t frames = bytes_per && ft->signal.channels ? data_bytes / (bytes_per * ft->signal.channels) : 0;
    fseek(ft->fp, 4, SEEK_SET);
    wr_le32f(ft, (uint32_t)(filesize - 8));
    /* fact frames patch: find fact chunk position */
    {
      /* recompute: fmt size known by tag */
      long factpos = 0;
      if (w->format_tag != 1 || w->raw.bits > 16) {
        /* extensible: 12 + 8+40 = 60 -> fact at 60; float/ulaw: 12 + 8+18=38 */
      }
      (void)factpos;
    }
    /* data size patch: data chunk size field = header end - 8 */
    fseek(ft->fp, (long)(w->raw.data_start - 4), SEEK_SET);
    wr_le32f(ft, (uint32_t)data_bytes);
    /* patch fact if present: scan */
    fseek(ft->fp, 12, SEEK_SET);
    for (;;) {
      char id[4]; uint32_t cs;
      long pos = ftell(ft->fp);
      if (fread(id, 1, 4, ft->fp) != 4) break;
      if (!rd_le32f(ft, &cs)) break;
      if (!memcmp(id, "fact", 4)) {
        wr_le32f(ft, (uint32_t)frames);
        break;
      }
      if (!memcmp(id, "data", 4)) break;
      if (fseek(ft->fp, pos + 8 + cs + (cs & 1), SEEK_SET)) break;
    }
    fseek(ft->fp, 0, SEEK_END);
  }
  free(ft->priv);
  return 0;
}

static const char * const wav_names_l[] = {"wav", "wavpcm", "amb", NULL};

const sox_format_handler_t sox_wav_handler = {
  "wav", 0, wav_startread, wav_read, wav_stopread,
  wav_startwrite, wav_write, wav_stopwrite, NULL,
  "Microsoft audio format", wav_names_l, NULL
};

/* xsox - AU/SND format handler */
#include "xsox.h"
#include <errno.h>

typedef struct {
  raw_io_t raw;
  uint64_t data_size;
} au_t;

static int rd_be32a(sox_format_t * ft, uint32_t * v)
{ int a = fgetc(ft->fp), b = fgetc(ft->fp), c = fgetc(ft->fp), d = fgetc(ft->fp);
  if (d == EOF) return 0; *v = ((uint32_t)a << 24) | ((uint32_t)b << 16) | ((uint32_t)c << 8) | (uint32_t)d; return 1; }
static int wr_be32a(sox_format_t * ft, uint32_t v)
{ return fputc((v >> 24) & 0xff, ft->fp) != EOF && fputc((v >> 16) & 0xff, ft->fp) != EOF &&
         fputc((v >> 8) & 0xff, ft->fp) != EOF && fputc(v & 0xff, ft->fp) != EOF; }

static int au_startread(sox_format_t * ft)
{
  char magic[4];
  uint32_t offset, size, code, rate, channels;
  au_t * a = calloc(1, sizeof *a);
  ft->priv = a;

  if (fread(magic, 1, 4, ft->fp) != 4 || memcmp(magic, ".snd", 4)) {
    ft->sox_errno = 1;
    snprintf(ft->errstr, sizeof ft->errstr, "AU: not an AU file");
    return 1;
  }
  if (!rd_be32a(ft, &offset) || !rd_be32a(ft, &size) || !rd_be32a(ft, &code) ||
      !rd_be32a(ft, &rate) || !rd_be32a(ft, &channels)) {
    ft->sox_errno = 1;
    snprintf(ft->errstr, sizeof ft->errstr, "AU: error reading header");
    return 1;
  }
  if (offset < 24) offset = 24;

  switch (code) {
    case 1: ft->encoding.encoding = SOX_ENCODING_ULAW; ft->encoding.bits = 8; ft->encoding.precision = 14; break;
    case 2: ft->encoding.encoding = SOX_ENCODING_SIGN2; ft->encoding.bits = 8; ft->encoding.precision = 8; break;
    case 3: ft->encoding.encoding = SOX_ENCODING_SIGN2; ft->encoding.bits = 16; ft->encoding.precision = 16; break;
    case 4: ft->encoding.encoding = SOX_ENCODING_SIGN2; ft->encoding.bits = 24; ft->encoding.precision = 24; break;
    case 5: ft->encoding.encoding = SOX_ENCODING_SIGN2; ft->encoding.bits = 32; ft->encoding.precision = 32; break;
    case 6: ft->encoding.encoding = SOX_ENCODING_FLOAT; ft->encoding.bits = 32; ft->encoding.precision = 25; break;
    case 7: ft->encoding.encoding = SOX_ENCODING_FLOAT; ft->encoding.bits = 64; ft->encoding.precision = 54; break;
    case 23: case 26: /* gsm */ ft->encoding.encoding = SOX_ENCODING_GSM; ft->encoding.bits = 0; break;
    case 27: ft->encoding.encoding = SOX_ENCODING_ALAW; ft->encoding.bits = 8; ft->encoding.precision = 13; break;
    default:
      ft->sox_errno = 1;
      snprintf(ft->errstr, sizeof ft->errstr, "AU: unsupported encoding %u", code);
      return 1;
  }
  ft->encoding.endian = 1;
  if (!ft->signal.rate) ft->signal.rate = rate;
  if (!ft->signal.channels) ft->signal.channels = channels;
  if (!ft->signal.precision) ft->signal.precision = ft->encoding.precision;

  {
    unsigned bytes_per = (ft->encoding.bits + 7) / 8;
    if (size != 0xffffffffu && bytes_per && channels)
      ft->signal.length = (uint64_t)(size / bytes_per);
    else if (ft->seekable)
      ft->signal.length = ft->io_size > offset ? (ft->io_size - offset) / bytes_per : 0;
    else
      ft->signal.length = 0;
  }

  /* annotation */
  if (offset > 24) {
    size_t n = offset - 24;
    char * buf = malloc(n + 1);
    if (fread(buf, 1, n, ft->fp) == n) {
      buf[n] = 0;
      if (buf[0]) ft->comment = strdup(buf);
    }
    free(buf);
  } else {
    fseek(ft->fp, offset, SEEK_SET);
  }

  a->raw.encoding = ft->encoding.encoding;
  a->raw.bits = ft->encoding.bits;
  a->raw.endian = 1;
  a->raw.data_start = offset;
  ft->tell_off = offset;
  a->raw.data_length = ft->signal.length * ((ft->encoding.bits + 7) / 8);
  a->data_size = a->raw.data_length;
  return 0;
}

static size_t au_read(sox_format_t * ft, sox_sample_t * buf, size_t len)
{ return raw_read(ft, buf, len); }

static int au_stopread(sox_format_t * ft)
{ free(ft->priv); return 0; }

static int au_startwrite(sox_format_t * ft)
{
  au_t * a = calloc(1, sizeof *a);
  unsigned code;
  unsigned bits = ft->encoding.bits;
  const char * comment = ft->comment ? ft->comment : "Processed by SoX";
  size_t clen = strlen(comment) + 1;
  size_t offset = 24 + ((clen + 3) & ~3u);

  ft->priv = a;
  if (!bits) bits = 16;
  switch (ft->encoding.encoding) {
    case SOX_ENCODING_ULAW: code = 1; bits = 8; break;
    case SOX_ENCODING_SIGN2:
      code = bits == 8 ? 2 : bits == 16 ? 3 : bits == 24 ? 4 : 5;
      break;
    case SOX_ENCODING_FLOAT: code = bits == 64 ? 7 : 6; break;
    case SOX_ENCODING_ALAW: code = 27; bits = 8; break;
    case SOX_ENCODING_UNSIGNED: code = 2; bits = 8; ft->encoding.encoding = SOX_ENCODING_SIGN2; break;
    default: code = 3; bits = 16; break;
  }

  fwrite(".snd", 1, 4, ft->fp);
  wr_be32a(ft, (uint32_t)offset);
  wr_be32a(ft, ft->seekable ? 0 : 0xffffffffu); /* patch size later */
  wr_be32a(ft, code);
  wr_be32a(ft, (unsigned)(ft->signal.rate + 0.5));
  wr_be32a(ft, ft->signal.channels);
  {
    size_t i;
    for (i = 0; i < clen; i++) fputc(comment[i], ft->fp);
    for (; i < offset - 24; i++) fputc(0, ft->fp);
  }

  a->raw.encoding = ft->encoding.encoding;
  a->raw.bits = bits;
  a->raw.endian = 1;
  a->raw.data_start = offset;
  ft->tell_off = offset;
  ft->data_length = 0;
  ft->encoding.bits = bits;
  return 0;
}

static size_t au_write(sox_format_t * ft, const sox_sample_t * buf, size_t len)
{ return raw_write(ft, buf, len); }

static int au_stopwrite(sox_format_t * ft)
{
  au_t * a = ft->priv;
  if (ft->seekable) {
    fseek(ft->fp, 8, SEEK_SET);
    wr_be32a(ft, (uint32_t)ft->data_length);
    fseek(ft->fp, 0, SEEK_END);
  }
  free(a);
  return 0;
}

static const char * const au_names_l[] = {"au", "snd", NULL};

const sox_format_handler_t sox_au_handler = {
  "au", 0, au_startread, au_read, au_stopread,
  au_startwrite, au_write, au_stopwrite, NULL,
  "PCM file format used widely on Sun systems", au_names_l, NULL
};

/* xsox - AIFF/AIFC format handler */
#include "xsox.h"
#include <errno.h>

typedef struct {
  raw_io_t raw;
  uint64_t data_size;
  long comm_pos;      /* position of COMM frames field */
  long form_pos;
} aiff_t;

static int rd_be32i(sox_format_t * ft, uint32_t * v)
{ int a = fgetc(ft->fp), b = fgetc(ft->fp), c = fgetc(ft->fp), d = fgetc(ft->fp);
  if (d == EOF) return 0; *v = ((uint32_t)a << 24) | ((uint32_t)b << 16) | ((uint32_t)c << 8) | (uint32_t)d; return 1; }
static int rd_be16i(sox_format_t * ft, unsigned * v)
{ int a = fgetc(ft->fp), b = fgetc(ft->fp); if (b == EOF) return 0; *v = (unsigned)((a << 8) | b); return 1; }
static int wr_be32i(sox_format_t * ft, uint32_t v)
{ return fputc((v >> 24) & 0xff, ft->fp) != EOF && fputc((v >> 16) & 0xff, ft->fp) != EOF &&
         fputc((v >> 8) & 0xff, ft->fp) != EOF && fputc(v & 0xff, ft->fp) != EOF; }
static int wr_be16i(sox_format_t * ft, unsigned v)
{ return fputc((v >> 8) & 0xff, ft->fp) != EOF && fputc(v & 0xff, ft->fp) != EOF; }

/* 80-bit extended float for sample rate */
static void wr_extended(sox_format_t * ft, double rate)
{
  unsigned char b[10] = {0};
  if (rate > 0) {
    int exp;
    double mant = frexp(rate, &exp);   /* rate = mant * 2^exp, mant in [0.5,1) */
    uint64_t m = (uint64_t)ldexp(mant * 2, 63); /* 1.xxx * 2^63 */
    unsigned e = (unsigned)(exp - 1 + 16383);
    b[0] = (e >> 8) & 0x7f;
    b[1] = e & 0xff;
    b[2] = (m >> 56) & 0xff;
    b[3] = (m >> 48) & 0xff;
    b[4] = (m >> 40) & 0xff;
    b[5] = (m >> 32) & 0xff;
    b[6] = (m >> 24) & 0xff;
    b[7] = (m >> 16) & 0xff;
    b[8] = (m >> 8) & 0xff;
    b[9] = m & 0xff;
  }
  fwrite(b, 1, 10, ft->fp);
}

static double rd_extended(sox_format_t * ft)
{
  unsigned char b[10];
  unsigned e;
  uint64_t m;
  if (fread(b, 1, 10, ft->fp) != 10) return 0;
  e = ((b[0] & 0x7f) << 8) | b[1];
  m = ((uint64_t)b[2] << 56) | ((uint64_t)b[3] << 48) | ((uint64_t)b[4] << 40) |
      ((uint64_t)b[5] << 32) | ((uint64_t)b[6] << 24) | ((uint64_t)b[7] << 16) |
      ((uint64_t)b[8] << 8) | b[9];
  if (e == 0 && m == 0) return 0;
  return ldexp((double)m, (int)e - 16383 - 63);
}

static int aiff_startread(sox_format_t * ft)
{
  char id[4];
  uint32_t form_size;
  int is_aifc = 0;
  aiff_t * a = calloc(1, sizeof *a);
  ft->priv = a;

  if (fread(id, 1, 4, ft->fp) != 4 || memcmp(id, "FORM", 4)) {
    ft->sox_errno = 1; snprintf(ft->errstr, sizeof ft->errstr, "AIFF: not an AIFF file");
    return 1;
  }
  if (!rd_be32i(ft, &form_size)) { ft->sox_errno = 1; return 1; }
  if (fread(id, 1, 4, ft->fp) != 4) { ft->sox_errno = 1; return 1; }
  if (!memcmp(id, "AIFC")) is_aifc = 1;
  else if (memcmp(id, "AIFF")) {
    ft->sox_errno = 1; snprintf(ft->errstr, sizeof ft->errstr, "AIFF: not an AIFF file");
    return 1;
  }

  for (;;) {
    uint32_t csize;
    long next;
    if (fread(id, 1, 4, ft->fp) != 4) break;
    if (!rd_be32i(ft, &csize)) break;
    next = ftell(ft->fp) + csize + (csize & 1);
    if (!memcmp(id, "COMM", 4)) {
      unsigned channels, bits;
      uint32_t frames;
      double rate;
      if (!rd_be16i(ft, &channels)) break;
      if (!rd_be32i(ft, &frames)) break;
      if (!rd_be16i(ft, &bits)) break;
      rate = rd_extended(ft);
      if (is_aifc) {
        char comp[4];
        if (fread(comp, 1, 4, ft->fp) != 4) break;
        if (!memcmp(comp, "sowt", 4)) {
          ft->encoding.encoding = SOX_ENCODING_SIGN2;
          ft->encoding.endian = 0;
        } else if (!memcmp(comp, "NONE", 4) || !memcmp(comp, "twos", 4)) {
          ft->encoding.encoding = SOX_ENCODING_SIGN2;
          ft->encoding.endian = 1;
        } else if (!memcmp(comp, "fl32", 4) || !memcmp(comp, "FL32", 4)) {
          ft->encoding.encoding = SOX_ENCODING_FLOAT; ft->encoding.endian = 1;
        } else if (!memcmp(comp, "fl64", 4) || !memcmp(comp, "FL64", 4)) {
          ft->encoding.encoding = SOX_ENCODING_FLOAT; ft->encoding.endian = 1;
        } else if (!memcmp(comp, "ulaw", 4) || !memcmp(comp, "ULAW", 4)) {
          ft->encoding.encoding = SOX_ENCODING_ULAW; ft->encoding.endian = 1;
        } else if (!memcmp(comp, "alaw", 4) || !memcmp(comp, "ALAW", 4)) {
          ft->encoding.encoding = SOX_ENCODING_ALAW; ft->encoding.endian = 1;
        } else if (!memcmp(comp, "in24", 4) || !memcmp(comp, "in32", 4)) {
          ft->encoding.encoding = SOX_ENCODING_SIGN2; ft->encoding.endian = 1;
        } else {
          ft->sox_errno = 1;
          snprintf(ft->errstr, sizeof ft->errstr, "AIFF: unsupported AIFC compression `%.4s'", comp);
          return 1;
        }
      } else {
        ft->encoding.encoding = SOX_ENCODING_SIGN2;
        ft->encoding.endian = 1;
      }
      ft->encoding.bits = bits;
      ft->encoding.precision = bits;
      if (ft->encoding.encoding == SOX_ENCODING_ULAW) ft->encoding.precision = 14;
      if (ft->encoding.encoding == SOX_ENCODING_ALAW) ft->encoding.precision = 13;
      if (!ft->signal.rate) ft->signal.rate = rate;
      if (!ft->signal.channels) ft->signal.channels = channels;
      if (!ft->signal.precision) ft->signal.precision = ft->encoding.precision;
      ft->signal.length = (uint64_t)frames * channels;
    } else if (!memcmp(id, "SSND", 4)) {
      uint32_t offset, blocksize;
      if (!rd_be32i(ft, &offset) || !rd_be32i(ft, &blocksize)) break;
      if (offset) fseek(ft->fp, offset, SEEK_CUR);
      a->raw.data_start = ftell(ft->fp);
      ft->tell_off = a->raw.data_start;
      a->raw.data_length = csize - 8 - offset;
      a->data_size = a->raw.data_length;
      a->raw.encoding = ft->encoding.encoding;
      a->raw.bits = ft->encoding.bits;
      a->raw.endian = ft->encoding.endian == 1;
      return 0;
    } else if (!memcmp(id, "COMT", 4)) {
      /* skip for now */
    }
    if (fseek(ft->fp, next, SEEK_SET)) break;
  }
  ft->sox_errno = 1;
  snprintf(ft->errstr, sizeof ft->errstr, "AIFF: missing SSND chunk");
  return 1;
}

static size_t aiff_read(sox_format_t * ft, sox_sample_t * buf, size_t len)
{ return raw_read(ft, buf, len); }

static int aiff_stopread(sox_format_t * ft)
{ free(ft->priv); return 0; }

static int aiff_startwrite(sox_format_t * ft)
{
  aiff_t * a = calloc(1, sizeof *a);
  int is_aifc = ft->handler && !strcmp(ft->handler->name, "aifc");
  const char * comment = ft->comment ? ft->comment : "Processed by SoX";
  size_t clen = strlen(comment);
  unsigned bits = ft->encoding.bits ? ft->encoding.bits : 16;

  ft->priv = a;

  fwrite("FORM", 1, 4, ft->fp);
  wr_be32i(ft, 0); /* patch */
  fwrite(is_aifc ? "AIFC" : "AIFF", 1, 4, ft->fp);

  /* COMT chunk (as written by reference: before COMM) */
  if (clen) {
    size_t csz = 2 + (4 + 2 + 2 + clen);
    fwrite("COMT", 1, 4, ft->fp);
    wr_be32i(ft, (uint32_t)csz);
    wr_be16i(ft, 1);            /* num comments */
    wr_be32i(ft, 0xe69fca71u);  /* timestamp (matches reference) */
    wr_be16i(ft, 0);            /* marker */
    wr_be16i(ft, (unsigned)clen);
    fwrite(comment, 1, clen, ft->fp);
    if (csz & 1) fputc(0, ft->fp);
  }

  /* COMM */
  fwrite("COMM", 1, 4, ft->fp);
  wr_be32i(ft, is_aifc ? 22 : 18);
  wr_be16i(ft, ft->signal.channels);
  a->comm_pos = ftell(ft->fp);
  wr_be32i(ft, 0); /* frames, patch */
  wr_be16i(ft, bits);
  wr_extended(ft, ft->signal.rate);
  if (is_aifc) {
    fwrite("NONE", 1, 4, ft->fp);
    /* pstring name: "\015not compressed" padded even */
    fwrite("\016not compressed", 1, 15, ft->fp);
    fputc(0, ft->fp);
  }

  /* SSND */
  fwrite("SSND", 1, 4, ft->fp);
  wr_be32i(ft, 0); /* patch */
  wr_be32i(ft, 0); /* offset */
  wr_be32i(ft, 0); /* blocksize */

  a->raw.encoding = ft->encoding.encoding == SOX_ENCODING_UNKNOWN ? SOX_ENCODING_SIGN2 : ft->encoding.encoding;
  a->raw.bits = bits;
  a->raw.endian = 1;
  a->raw.data_start = ftell(ft->fp);
  ft->tell_off = a->raw.data_start;
  ft->data_length = 0;
  ft->encoding.encoding = a->raw.encoding;
  ft->encoding.bits = bits;
  ft->encoding.endian = 1;
  return 0;
}

static size_t aiff_write(sox_format_t * ft, const sox_sample_t * buf, size_t len)
{ return raw_write(ft, buf, len); }

static int aiff_stopwrite(sox_format_t * ft)
{
  aiff_t * a = ft->priv;
  unsigned bytes_per = (a->raw.bits + 7) / 8;
  uint64_t data_bytes = ft->data_length;

  if (data_bytes & 1) fputc(0, ft->fp);

  if (ft->seekable) {
    long end = ftell(ft->fp);
    uint64_t frames = bytes_per && ft->signal.channels ? data_bytes / (bytes_per * ft->signal.channels) : 0;
    /* FORM size */
    fseek(ft->fp, 4, SEEK_SET);
    wr_be32i(ft, (uint32_t)(end - 8));
    /* COMM frames */
    fseek(ft->fp, a->comm_pos, SEEK_SET);
    wr_be32i(ft, (uint32_t)frames);
    /* SSND size = data + 8 */
    fseek(ft->fp, a->raw.data_start - 12, SEEK_SET);
    wr_be32i(ft, (uint32_t)(data_bytes + 8));
    fseek(ft->fp, 0, SEEK_END);
  }
  free(a);
  return 0;
}

static const char * const aiff_names_l[] = {"aiff", "aif", NULL};
static const char * const aifc_names_l[] = {"aifc", "aiffc", NULL};

const sox_format_handler_t sox_aiff_handler = {
  "aiff", 0, aiff_startread, aiff_read, aiff_stopread,
  aiff_startwrite, aiff_write, aiff_stopwrite, NULL,
  "AIFF files used on Apple IIc/IIgs and SGI", aiff_names_l, NULL
};
const sox_format_handler_t sox_aifc_handler = {
  "aifc", 0, aiff_startread, aiff_read, aiff_stopread,
  aiff_startwrite, aiff_write, aiff_stopwrite, NULL,
  "AIFF-C (not compressed), defined in DAVIC 1.4 Part 9 Annex B", aifc_names_l, NULL
};

/* xsox - effects: engine + basic effects */
#include "xsox.h"
#include <ctype.h>
#include <errno.h>

/* ---------- effect registry entry ---------- */

#define EFF(name) static const sox_effect_handler_t name##_h
extern const sox_effect_handler_t * const sox_effect_handlers[];

const sox_effect_handler_t * sox_find_effect(const char * name)
{
  int i;
  for (i = 0; sox_effect_handlers[i]; i++)
    if (!strcmp(name, sox_effect_handlers[i]->name))
      return sox_effect_handlers[i];
  return NULL;
}

effect_t * sox_create_effect(const sox_effect_handler_t * h)
{
  effect_t * e = calloc(1, sizeof *e);
  e->handler = h;
  e->name = strdup(h->name);
  return e;
}

void sox_delete_effect(effect_t * e)
{
  if (!e) return;
  free(e->rbuf);
  free(e->priv);
  free(e->name);
  free(e);
}

/* ---------- input helpers ---------- */

/* fill residual buffer up to want samples; returns available */
static size_t eff_fill(effect_t * e, size_t want)
{
  while (e->rlen < want && !e->in_eof) {
    size_t need = want - e->rlen;
    size_t got;
    if (e->rcap < e->rlen + need) {
      e->rcap = (e->rlen + need) * 2;
      e->rbuf = realloc(e->rbuf, e->rcap * sizeof(sox_sample_t));
    }
    got = e->input(e, e->rbuf + e->rlen, need);
    if (got == 0) e->in_eof = 1;
    e->rlen += got;
    e->total_in += got;
  }
  return e->rlen;
}

static void eff_consume(effect_t * e, size_t n)
{
  if (n >= e->rlen) { e->rlen = 0; return; }
  memmove(e->rbuf, e->rbuf + n, (e->rlen - n) * sizeof(sox_sample_t));
  e->rlen -= n;
}

/* clip counting */
static sox_sample_t eclip(effect_t * e, double v)
{
  if (v > SOX_SAMPLE_MAX) { e->clips++; return (sox_sample_t)SOX_SAMPLE_MAX; }
  if (v < SOX_SAMPLE_MIN) { e->clips++; return (sox_sample_t)SOX_SAMPLE_MIN; }
  return (sox_sample_t)v;
}

/* parse a number with optional k/M suffix */
static double parse_num(const char * s, int * ok)
{
  char * end;
  double v = strtod(s, &end);
  *ok = 1;
  if (*end == 'k' || *end == 'K') { v *= 1000; end++; }
  else if (*end == 'M') { v *= 1000000; end++; }
  if (*end || end == s) *ok = 0;
  return v;
}

/* parse time/position spec: returns samples; kind: 0=time,1=samples,2=relative(+/-) */
uint64_t sox_parse_position(const char * s, const sox_signalinfo_t * sig, int * is_samples, int * relative)
{
  double v = 0;
  int ok = 0;
  *is_samples = 0;
  *relative = 0;
  if (!s || !*s) return 0;
  if (*s == '+') { *relative = 1; s++; }
  else if (*s == '-') { *relative = -1; s++; }
  if (*s == '=') { s++; }
  {
    size_t l = strlen(s);
    if (l && s[l-1] == 's') {
      /* samples */
      char * tmp = strndup(s, l - 1);
      v = strtod(tmp, NULL);
      free(tmp);
      *is_samples = 1;
      ok = 1;
    } else if (strchr(s, ':')) {
      /* hh:mm:ss.frac or mm:ss.frac */
      double t = 0;
      char * dup = strdup(s);
      char * p = dup;
      char * parts[4]; int n = 0;
      char * tok = strtok(p, ":");
      while (tok && n < 4) { parts[n++] = tok; tok = strtok(NULL, ":"); }
      if (n == 2) t = strtod(parts[0], NULL) * 60 + strtod(parts[1], NULL);
      else if (n == 3) t = strtod(parts[0], NULL) * 3600 + strtod(parts[1], NULL) * 60 + strtod(parts[2], NULL);
      else t = strtod(s, NULL);
      free(dup);
      v = t * sig->rate;
      ok = 1;
    } else {
      v = strtod(s, NULL) * sig->rate;
      ok = 1;
    }
  }
  (void)ok;
  if (v < 0) v = -v;
  return (uint64_t)(v + 0.5);
}

