/* trim */
typedef struct {
  uint64_t start, length;  /* samples per channel */
  int has_length;
  uint64_t pos;            /* current frame pos */
} trim_t;

static int trim_getopts(effect_t * e, int argc, char ** argv)
{
  trim_t * t = calloc(1, sizeof *t);
  e->priv = t;
  if (argc < 1) return -1;
  {
    int is_samp, rel;
    t->start = sox_parse_position(argv[0], &e->in_signal, &is_samp, &rel);
  }
  if (argc > 1) {
    int is_samp, rel;
    t->length = sox_parse_position(argv[1], &e->in_signal, &is_samp, &rel);
    if (rel < 0) {
      /* length relative to end: needs total length; handled at start */
      t->has_length = 2;
    } else if (rel > 0) {
      t->has_length = 1; /* +n means from start */
    } else {
      /* absolute end position: sox treats second arg as length unless '=' prefix */
      t->has_length = 1;
    }
  } else t->has_length = 0;
  return 0;
}
static int trim_start(effect_t * e)
{
  trim_t * t = e->priv;
  (void)e;
  t->pos = 0;
  if (t->has_length == 2 && e->in_signal.length) {
    uint64_t total = e->in_signal.length / (e->in_signal.channels ? e->in_signal.channels : 1);
    t->length = total > t->length + t->start ? total - t->start - t->length : 0;
    t->has_length = 1;
  }
  return 0;
}
static size_t trim_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  trim_t * t = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t nframes = is / ch, oframes = 0;
  size_t i = 0;
  while (i < nframes && oframes * ch < omax) {
    uint64_t p = t->pos;
    int keep = 0;
    if (p >= t->start && (!t->has_length || p - t->start < t->length)) keep = 1;
    if (keep) {
      unsigned c;
      for (c = 0; c < ch && oframes * ch + c < omax; c++)
        ob[oframes * ch + c] = ib[i * ch + c];
      oframes++;
    }
    t->pos++;
    i++;
    if (t->has_length && t->pos >= t->start + t->length && t->has_length) {
      /* can stop early; consume rest and signal done by just passing through */
      break;
    }
  }
  e->consumed = i * ch;
  return oframes * ch;
}
EFF(trim) = {"trim", "{POSITION}", NULL, trim_getopts, trim_start, trim_flow, NULL, NULL, 0};

