/* pad: pad {length[@position]} */
typedef struct {
  uint64_t pre, post;      /* frames (simplified: pre at 0, post at end) */
  uint64_t emitted;        /* post zeros emitted */
  int started;
} pad_t;

static int pad_getopts(effect_t * e, int argc, char ** argv)
{
  pad_t * p = calloc(1, sizeof *p);
  int i;
  e->priv = p;
  for (i = 0; i < argc; i++) {
    char * at = strchr(argv[i], '@');
    int is_samp, rel;
    if (at) *at = 0;
    {
      uint64_t n = sox_parse_position(argv[i], &e->in_signal, &is_samp, &rel);
      if (at) {
        /* at position */
        uint64_t pos = sox_parse_position(at + 1, &e->in_signal, &is_samp, &rel);
        if (pos == 0) p->pre = n; /* simplification */
        else p->pre = n; /* unsupported middle pad: approximate at 0 */
        (void)pos;
      } else {
        if (i == 0) p->pre = n; else p->post = n;
      }
    }
  }
  return 0;
}
static int pad_start(effect_t * e) { pad_t * p = e->priv; p->emitted = 0; p->started = 0; return 0; }
static size_t pad_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  pad_t * p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t out = 0;
  /* emit pre zeros first */
  if (!p->started) {
    uint64_t n = p->pre * ch;
    if (n > omax) n = omax;
    memset(ob, 0, n * sizeof(sox_sample_t));
    out += n;
    p->started = 1;
    if (out == omax) { p->pre -= out / ch; p->started = p->pre == 0; e->consumed = 0; return out; }
    p->pre = 0;
  }
  {
    size_t n = is;
    if (n > omax - out) n = omax - out;
    memcpy(ob + out, ib, n * sizeof(sox_sample_t));
    out += n;
    e->consumed = n;
  }
  return out;
}
static size_t pad_drain(effect_t * e, sox_sample_t * ob, size_t omax)
{
  pad_t * p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  uint64_t remain = (p->post - p->emitted) * ch;
  size_t n = remain > omax ? omax : (size_t)remain;
  memset(ob, 0, n * sizeof(sox_sample_t));
  p->emitted += n / ch;
  return n;
}
EFF(pad) = {"pad", "{LENGTH[@POSITION]}", NULL, pad_getopts, pad_start, pad_flow, pad_drain, NULL, 0};

