/* fade */
typedef struct {
  uint64_t in_len, out_len;   /* frames */
  uint64_t in_done, out_total;
  uint64_t total;             /* total frames (for fade out) */
  char type;                  /* t q h l p */
  int do_in, do_out;
} fade_t;

static double fade_gain(char type, double x)
{
  switch (type) {
    case 'q': return x * x * x; /* quartic? placeholder */
    case 'h': return (1 - cos(x * M_PI)) / 2; /* sine? */
    case 'l': default: return x;
    case 'p': return x * x * (3 - 2 * x);
  }
}

static int fade_getopts(effect_t * e, int argc, char ** argv)
{
  fade_t * f = calloc(1, sizeof *f);
  int i = 0;
  e->priv = f;
  f->type = 't';
  f->do_in = 0; f->do_out = 0;
  if (argc > 0 && argv[0][0] && strchr("tqhlop", argv[0][0]) && !argv[0][1]) {
    f->type = argv[0][0];
    i = 1;
  }
  if (i < argc) {
    int is_samp, rel;
    f->in_len = sox_parse_position(argv[i], &e->in_signal, &is_samp, &rel);
    if (f->in_len) f->do_in = 1;
    i++;
  }
  if (i < argc) {
    int is_samp, rel;
    /* stop position for fade-in (ignored: length only), then fade-out length */
    i++;
  }
  if (i < argc) {
    int is_samp, rel;
    f->out_len = sox_parse_position(argv[i], &e->in_signal, &is_samp, &rel);
    if (f->out_len) f->do_out = 1;
  }
  return 0;
}
static int fade_start(effect_t * e)
{
  fade_t * f = e->priv;
  f->in_done = 0;
  if (e->in_signal.length)
    f->total = e->in_signal.length / (e->in_signal.channels ? e->in_signal.channels : 1);
  else
    f->total = 0;
  return 0;
}
static size_t fade_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  fade_t * f = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t nframes = is / ch;
  if (nframes * ch > omax) nframes = omax / ch;
  size_t i;
  for (i = 0; i < nframes; i++) {
    double g = 1.0;
    uint64_t p = f->in_done + i;
    if (f->do_in && p < f->in_len) {
      double x = (double)p / (double)f->in_len;
      g *= fade_gain(f->type, x);
    }
    if (f->do_out && f->total) {
      uint64_t out_start = f->total > f->out_len ? f->total - f->out_len : 0;
      if (p >= out_start) {
        double x = (double)(f->total - p) / (double)f->out_len;
        g *= fade_gain(f->type, x);
      }
    }
    {
      unsigned c;
      for (c = 0; c < ch; c++) ob[i * ch + c] = eclip(e, ib[i * ch + c] * g);
    }
  }
  f->in_done += nframes;
  e->consumed = nframes * ch;
  return nframes * ch;
}
EFF(fade) = {"fade", "[TYPE] FADE-IN-LENGTH [STOP-TIME [FADE-OUT-LENGTH]]", NULL, fade_getopts, fade_start, fade_flow, NULL, NULL, 0};

