        r->vol[i * 8 + n] = vol;
        n++;
        tok = strtok_r(NULL, ",", &save);
      }
      r->n_in[i] = n;
    }
    if (i + 1 > maxo) maxo = i + 1;
  }
  r->out_ch = maxo;
  return 0;
}
static int remix_start(effect_t * e)
{
  e->out_signal.channels = ((remix_t *)e->priv)->out_ch;
  return 0;
}
static size_t remix_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  remix_t * r = e->priv;
  unsigned ich = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t nframes = is / ich, i, out = 0;
  while (nframes && out + (size_t)r->out_ch <= omax) {
    int oc;
    for (oc = 0; oc < r->out_ch; oc++) {
      if (r->n_in[oc] == 0) ob[out + oc] = 0;
      else {
        double sum = 0;
        int k;
        for (k = 0; k < r->n_in[oc]; k++) {
          int ic = r->in_map[oc * 8 + k];
          if ((unsigned)ic < ich) sum += ib[out / r->out_ch * ich + ic] * r->vol[oc * 8 + k];
        }
        ob[out + oc] = eclip(e, sum / r->n_in[oc]);
      }
    }
    out += r->out_ch;
    nframes--;
  }
  e->consumed = out / r->out_ch * ich;
  return out;
}
