static void apply_raw_defaults(sox_format_t * ft)
{
  const raw_default_t * d;
  if (!ft->handler) return;
  for (d = raw_defaults; d->name; d++) {
    if (!strcmp(ft->handler->name, d->name)) {
      if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN && d->enc != SOX_ENCODING_UNKNOWN) {
        ft->encoding.encoding = d->enc;
        if (!ft->encoding.bits) ft->encoding.bits = d->bits;
      } else if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN && d->enc == SOX_ENCODING_UNKNOWN) {
        /* plain raw: default s16 */
        if (ft->mode == 'w' || ft->encoding.bits) {
          ft->encoding.encoding = SOX_ENCODING_SIGN2;
          if (!ft->encoding.bits) ft->encoding.bits = 16;
        }
      }
      if (!ft->encoding.bits && d->bits) ft->encoding.bits = d->bits;
      if (ft->encoding.endian < 0 && d->endian >= 0) ft->encoding.endian = d->endian;
      if (!ft->signal.rate && d->rate) ft->signal.rate = d->rate;
      if (!ft->signal.channels && d->channels) ft->signal.channels = d->channels;
      return;
    }
  }
}

static int raw_startread(sox_format_t * ft)
{
  raw_io_t * r = calloc(1, sizeof *r);
  int rc;
  apply_raw_defaults(ft);
  if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN) {
    ft->sox_errno = 1;
    snprintf(ft->errstr, sizeof ft->errstr, "bad input format for file `%s': sample rate zero or negative", ft->filename);
    free(r);
    return 1;
  }
  if (ft->signal.rate <= 0) {
    ft->sox_errno = 1;
    snprintf(ft->errstr, sizeof ft->errstr, "bad input format for file `%s': sample rate zero or negative", ft->filename);
    free(r);
    return 1;
  }
  rc = raw_start_common(ft, r);
  if (!ft->signal.channels) ft->signal.channels = 1;
  if (!ft->signal.precision) ft->signal.precision = ft->encoding.bits;
  if (ft->encoding.encoding == SOX_ENCODING_ULAW) ft->signal.precision = 14;
  if (ft->encoding.encoding == SOX_ENCODING_ALAW) ft->signal.precision = 13;
  if (ft->encoding.encoding == SOX_ENCODING_FLOAT) ft->signal.precision = ft->encoding.bits == 64 ? 54 : 25;
  /* length from file size */
  if (!ft->signal.length && ft->seekable && ft->io_size) {
    unsigned bytes_per = (ft->encoding.bits + 7) / 8;
    if (bytes_per) ft->signal.length = ft->io_size / bytes_per;
  }
  return rc;
}

