/* xsox - WAV (RIFF) format handler */
#include "xsox.h"
#include <errno.h>

typedef struct {
  raw_io_t raw;
  uint64_t data_size;
  uint64_t num_frames;
  unsigned format_tag;
  int extensible;
  int have_fact;
  long fact_value_pos; /* file pos of fact value, -1 none */
} wav_t;

static const char * wav_enc_name(sox_encoding_t e)
{
  switch (e) {
    case SOX_ENCODING_SIGN2: return "Signed Integer PCM";
    case SOX_ENCODING_UNSIGNED: return "Unsigned Integer PCM";
    case SOX_ENCODING_FLOAT: return "Floating Point PCM";
    case SOX_ENCODING_ULAW: return "u-law";
    case SOX_ENCODING_ALAW: return "A-law";
    case SOX_ENCODING_GSM: return "GSM";
    case SOX_ENCODING_IMA_ADPCM: return "IMA ADPCM";
    case SOX_ENCODING_MS_ADPCM: return "MS ADPCM";
    default: return "unknown";
  }
}

static int rd_le16f(sox_format_t * ft, unsigned * v)
{ int a = fgetc(ft->fp), b = fgetc(ft->fp); if (b == EOF) return 0; *v = (unsigned)(a | (b << 8)); return 1; }
static int rd_le32f(sox_format_t * ft, uint32_t * v)
{ unsigned a, b; if (!rd_le16f(ft, &a) || !rd_le16f(ft, &b)) return 0; *v = a | ((uint32_t)b << 16); return 1; }
static int rd_be32f(sox_format_t * ft, uint32_t * v)
{ int a = fgetc(ft->fp), b = fgetc(ft->fp), c = fgetc(ft->fp), d = fgetc(ft->fp);
  if (d == EOF) return 0; *v = ((uint32_t)a << 24) | ((uint32_t)b << 16) | ((uint32_t)c << 8) | (uint32_t)d; return 1; }
static int rd_be16f(sox_format_t * ft, unsigned * v)
{ int a = fgetc(ft->fp), b = fgetc(ft->fp); if (b == EOF) return 0; *v = (unsigned)((a << 8) | b); return 1; }
static int wr_le16f(sox_format_t * ft, unsigned v)
{ return fputc(v & 0xff, ft->fp) != EOF && fputc((v >> 8) & 0xff, ft->fp) != EOF; }
static int wr_le32f(sox_format_t * ft, uint32_t v)
{ return wr_le16f(ft, v & 0xffff) && wr_le16f(ft, v >> 16); }
static int wr_str4(sox_format_t * ft, const char * s)
{ return fwrite(s, 1, 4, ft->fp) == 4; }

static int wav_startread(sox_format_t * ft)
{
  char id[4];
  uint32_t riff_size, fmt_size = 0;
  unsigned tag = 0, channels = 0, bits = 0, blockalign = 0;
  uint32_t rate = 0;
  int is_rifx = 0;
  int have_fmt = 0;
  wav_t * w = calloc(1, sizeof *w);

  ft->priv = w;
  w->fact_value_pos = -1;

  if (fread(id, 1, 4, ft->fp) != 4 || (memcmp(id, "RIFF", 4) && memcmp(id, "RIFX", 4))) {
    ft->sox_errno = 1;
    snprintf(ft->errstr, sizeof ft->errstr, "WAVE: RIFF header not found");
    return 1;
  }
  is_rifx = !memcmp(id, "RIFX", 4);

  #define RD32(v) (is_rifx ? rd_be32f(ft, v) : rd_le32f(ft, v))
  #define RD16(v) (is_rifx ? rd_be16f(ft, v) : rd_le16f(ft, v))

  if (!RD32(&riff_size)) { ft->sox_errno = 1; ft->errstr[0] = 0; return 1; }
  if (fread(id, 1, 4, ft->fp) != 4 || memcmp(id, "WAVE", 4)) {
    ft->sox_errno = 1;
    snprintf(ft->errstr, sizeof ft->errstr, "WAVE header not found");
    return 1;
  }

  for (;;) {
    uint32_t csize;
    long next;
    if (fread(id, 1, 4, ft->fp) != 4) break;
    if (!RD32(&csize)) break;
    next = ftell(ft->fp) + csize + (csize & 1);
    if (!memcmp(id, "fmt ", 4)) {
      uint32_t dw;
      fmt_size = csize;
      if (!RD16(&tag)) goto hdr_trunc;
      if (!RD16(&channels)) goto hdr_trunc;
      if (!RD32(&rate)) goto hdr_trunc;
      if (!RD32(&dw)) goto hdr_trunc;
      if (!RD16(&blockalign)) goto hdr_trunc;
      if (csize >= 16) { if (!RD16(&bits)) goto hdr_trunc; }
      if (tag == 0xfffe && csize >= 40) {
        unsigned cb; uint32_t valid, mask; unsigned t2;
        if (!RD16(&cb)) goto hdr_trunc;
        if (!RD32(&valid)) goto hdr_trunc;
        if (!RD32(&mask)) goto hdr_trunc;
        if (!RD16(&t2)) goto hdr_trunc;
        (void)cb; (void)valid; (void)mask;
        tag = t2;
      }
      have_fmt = 1;
    } else if (!memcmp(id, "data", 4)) {
      if (!have_fmt) {
        ft->sox_errno = 1;
        snprintf(ft->errstr, sizeof ft->errstr, "fmt chunk not found");
        return 1;
      }
      w->data_size = csize;
      w->raw.data_start = ftell(ft->fp);
      ft->tell_off = w->raw.data_start;
      w->raw.data_length = csize;
      goto found_data;
    }
    if (fseek(ft->fp, next, SEEK_SET)) break;
  }
  ft->sox_errno = 1;
  snprintf(ft->errstr, sizeof ft->errstr, "%s", have_fmt ? "missing data chunk" : "fmt chunk not found");
  return 1;

hdr_trunc:
  ft->sox_errno = 1;
  ft->errstr[0] = 0;
  return 1;

found_data:
  if (fmt_size == 16 && tag != 1)
    sox_warn("wav", "WAVE file missing extended part of fmt chunk");
  switch (tag) {
    case 1: ft->encoding.encoding = bits == 8 ? SOX_ENCODING_UNSIGNED : SOX_ENCODING_SIGN2; break;
    case 3: ft->encoding.encoding = SOX_ENCODING_FLOAT; break;
    case 6: ft->encoding.encoding = SOX_ENCODING_ALAW; bits = 8; break;
    case 7: ft->encoding.encoding = SOX_ENCODING_ULAW; bits = 8; break;
    case 0x11:
      ft->sox_errno = 1;
      snprintf(ft->errstr, sizeof ft->errstr, "Unknown WAVE format %04x", tag);
      return 1;
    default:
      ft->sox_errno = 1;
      snprintf(ft->errstr, sizeof ft->errstr, "Unknown WAVE format %04x", tag);
      return 1;
  }
  w->format_tag = tag;
  ft->encoding.bits = bits;
  ft->encoding.precision = bits;
  if (ft->encoding.encoding == SOX_ENCODING_ULAW) ft->encoding.precision = 14;
  if (ft->encoding.encoding == SOX_ENCODING_ALAW) ft->encoding.precision = 13;
  if (ft->encoding.encoding == SOX_ENCODING_FLOAT) ft->encoding.precision = bits == 64 ? 54 : 25;
  if (ft->encoding.endian < 0) ft->encoding.endian = is_rifx ? 1 : 0;
  if (!ft->signal.rate) ft->signal.rate = rate;
  if (!ft->signal.channels) ft->signal.channels = channels;
  if (!ft->signal.precision) ft->signal.precision = ft->encoding.precision;
  w->num_frames = blockalign ? w->data_size / blockalign : 0;
  ft->signal.length = (uint64_t)w->num_frames * ft->signal.channels;

  w->raw.encoding = ft->encoding.encoding;
  w->raw.bits = ft->encoding.bits;
  w->raw.endian = is_rifx;
  return 0;
}

static size_t wav_read(sox_format_t * ft, sox_sample_t * buf, size_t len)
{
  size_t n = raw_read(ft, buf, len);
  if (n < len && n > 0)
    sox_warn("wav", "Premature EOF on .wav input file");
  return n;
}

static int wav_stopread(sox_format_t * ft)
{
  free(ft->priv);
  return 0;
}

/* ---------- writing ---------- */

static int wav_startwrite(sox_format_t * ft)
{
  wav_t * w = calloc(1, sizeof *w);
  unsigned tag;
  int extensible = 0, have_fact = 0;
  unsigned bits = ft->encoding.bits;
  unsigned channels = ft->signal.channels;
  unsigned rate = (unsigned)(ft->signal.rate + 0.5);
  unsigned blockalign, avg;
  sox_encoding_t enc = ft->encoding.encoding;

  ft->priv = w;
  w->fact_value_pos = -1;

  if (enc == SOX_ENCODING_UNKNOWN) { enc = SOX_ENCODING_SIGN2; if (!bits) bits = 16; }
  if (!bits) bits = 16;

  /* fallbacks for unsupported combos */
  if (enc == SOX_ENCODING_UNSIGNED && bits != 8) {
    sox_warn("formats", "wav can't encode %s to %u-bit", wav_enc_name(enc), bits);
    enc = SOX_ENCODING_UNSIGNED; bits = 8;
  } else if (enc == SOX_ENCODING_SIGN2 && bits == 8) {
    sox_warn("formats", "wav can't encode %s to %u-bit", wav_enc_name(enc), bits);
    enc = SOX_ENCODING_SIGN2; bits = 16;
  } else if (enc == SOX_ENCODING_FLOAT && bits != 32 && bits != 64) {
    sox_warn("formats", "wav can't encode %s to %u-bit", wav_enc_name(enc), bits);
    enc = SOX_ENCODING_FLOAT; bits = 32;
  } else if (enc == SOX_ENCODING_GSM) {
    sox_warn("formats", "wav can't encode %s", wav_enc_name(enc));
    enc = SOX_ENCODING_SIGN2; bits = 16;
  }

  switch (enc) {
    case SOX_ENCODING_SIGN2:
      tag = 1;
      if (bits > 16 || channels > 2) extensible = 1;
      break;
    case SOX_ENCODING_UNSIGNED:
      tag = 1; bits = 8;
      if (channels > 2) extensible = 1;
      break;
    case SOX_ENCODING_FLOAT:
      tag = 3; have_fact = 1;
      break;
    case SOX_ENCODING_ULAW:
      tag = 7; bits = 8; have_fact = 1;
      break;
    case SOX_ENCODING_ALAW:
      tag = 6; bits = 8; have_fact = 1;
      break;
    default:
      tag = 1; enc = SOX_ENCODING_SIGN2; bits = 16;
      break;
  }
  if (extensible) have_fact = 1;
  w->format_tag = tag;
  w->extensible = extensible;
  w->have_fact = have_fact;
  ft->encoding.encoding = enc;
  ft->encoding.bits = bits;

  blockalign = channels * ((bits + 7) / 8);
  avg = rate * blockalign;

  wr_str4(ft, "RIFF");
  wr_le32f(ft, 0);
  wr_str4(ft, "WAVE");
  wr_str4(ft, "fmt ");
  if (extensible) {
    wr_le32f(ft, 40);
    wr_le16f(ft, 0xfffe);
    wr_le16f(ft, channels);
    wr_le32f(ft, rate);
    wr_le32f(ft, avg);
    wr_le16f(ft, blockalign);
    wr_le16f(ft, bits);
    wr_le16f(ft, 22);
    wr_le16f(ft, bits);
    {
      uint32_t mask;
      switch (channels) {
        case 1: mask = 4; break;
        case 2: mask = 3; break;
        case 4: mask = 0x33; break;
        case 6: mask = 0x3f; break;
        case 8: mask = 0x63f; break;
        default: mask = 0; break;
      }
      wr_le32f(ft, mask);
    }
    wr_le16f(ft, tag);
    {
      static const unsigned char rest[14] = {0x00,0x00,0x00,0x00,0x10,0x00,0x80,0x00,0x00,0xaa,0x00,0x38,0x9b,0x71};
      fwrite(rest, 1, 14, ft->fp);
    }
  } else if (have_fact) {
    wr_le32f(ft, 18);
    wr_le16f(ft, tag);
    wr_le16f(ft, channels);
    wr_le32f(ft, rate);
    wr_le32f(ft, avg);
    wr_le16f(ft, blockalign);
    wr_le16f(ft, bits);
    wr_le16f(ft, 0);
  } else {
    wr_le32f(ft, 16);
    wr_le16f(ft, tag);
    wr_le16f(ft, channels);
    wr_le32f(ft, rate);
    wr_le32f(ft, avg);
    wr_le16f(ft, blockalign);
    wr_le16f(ft, bits);
  }
  if (have_fact) {
    wr_str4(ft, "fact");
    wr_le32f(ft, 4);
    w->fact_value_pos = ftell(ft->fp);
    wr_le32f(ft, 0);
  }
  wr_str4(ft, "data");
  wr_le32f(ft, 0);

  w->raw.encoding = enc;
  w->raw.bits = bits;
  w->raw.endian = 0;
  w->raw.data_start = ftell(ft->fp);
  ft->tell_off = w->raw.data_start;
  ft->data_length = 0;
  return 0;
}

static size_t wav_write(sox_format_t * ft, const sox_sample_t * buf, size_t len)
{
  return raw_write(ft, buf, len);
}

static int wav_stopwrite(sox_format_t * ft)
{
  wav_t * w = ft->priv;
  unsigned bytes_per = (w->raw.bits + 7) / 8;
  uint64_t data_bytes = ft->data_length;

  if (data_bytes & 1)
    fputc(0, ft->fp);

  if (ft->seekable) {
    long filesize = ftell(ft->fp);
    uint64_t frames = bytes_per && ft->signal.channels ? data_bytes / ((uint64_t)bytes_per * ft->signal.channels) : 0;
    fseek(ft->fp, 4, SEEK_SET);
    wr_le32f(ft, (uint32_t)(filesize - 8));
    if (w->fact_value_pos >= 0) {
      fseek(ft->fp, w->fact_value_pos, SEEK_SET);
      wr_le32f(ft, (uint32_t)frames);
    }
    fseek(ft->fp, (long)(w->raw.data_start - 4), SEEK_SET);
    wr_le32f(ft, (uint32_t)data_bytes);
    fseek(ft->fp, 0, SEEK_END);
  }
  free(ft->priv);
  return 0;
}

static const char * const wav_names_l[] = {"wav", "wavpcm", "amb", NULL};

const sox_format_handler_t sox_wav_handler = {
  "wav", 0, wav_startread, wav_read, wav_stopread,
  wav_startwrite, wav_write, wav_stopwrite, NULL,
  "Microsoft audio format", wav_names_l, NULL
};

