/* ============ effects chain engine ============ */

typedef struct {
  effect_t ** eff;
  int n;
  sox_format_t * in;       /* current input (concatenate) */
  sox_format_t ** ins;     /* mix/merge inputs */
  int n_in;
  int combine;             /* 0 concat, 1 mix, 2 mix-power, 3 merge, 4 multiply */
  double mix_scale;
  sox_sample_t * mixbuf;
} chain_t;

static size_t chain_read(chain_t * c, int i, sox_sample_t * buf, size_t max);

/* read from input file(s) */
static size_t input_read(chain_t * c, sox_sample_t * buf, size_t max)
{
  if (c->combine == 1 || c->combine == 2 || c->combine == 4) {
    /* mix: read from all, average */
    size_t got_max = 0;
    int k;
    memset(buf, 0, max * sizeof(sox_sample_t));
    if (!c->mixbuf) c->mixbuf = malloc(max * sizeof(sox_sample_t));
    for (k = 0; k < c->n_in; k++) {
      size_t got = c->ins[k]->handler->read(c->ins[k], c->mixbuf, max);
      size_t j;
      double scale = c->combine == 1 ? 1.0 / c->n_in :
                     c->combine == 2 ? 1.0 / sqrt((double)c->n_in) : 1.0;
      for (j = 0; j < got; j++) {
        double v = buf[j] + c->mixbuf[j] * scale;
        if (v > SOX_SAMPLE_MAX) v = SOX_SAMPLE_MAX;
        if (v < SOX_SAMPLE_MIN) v = SOX_SAMPLE_MIN;
        buf[j] = (sox_sample_t)v;
      }
      if (got > got_max) got_max = got;
    }
    return got_max;
  }
  /* concatenate / merge: single current input */
  return c->in->handler->read(c->in, buf, max);
}

static size_t chain_read(chain_t * c, int i, sox_sample_t * out, size_t max)
{
  effect_t * e;
  size_t total = 0;
  if (i < 0) return input_read(c, out, max);
  e = c->eff[i];
  while (total < max) {
    if (e->in_eof && e->rlen == 0) {
      size_t n = 0;
      if (e->drained) break;
      if (e->handler->drain) n = e->handler->drain(e, out + total, max - total);
      e->drained = 1;
      if (n == 0) break;
      total += n;
      continue;
    }
    /* need input */
    if (e->rlen == 0 && !e->in_eof) {
      size_t want = 8192;
      if (e->rcap < want) { e->rcap = want * 2; e->rbuf = realloc(e->rbuf, e->rcap * sizeof(sox_sample_t)); }
      {
        size_t got = chain_read(c, i - 1, e->rbuf, want);
        e->rlen = got;
        if (got == 0) { e->in_eof = 1; continue; }
      }
    }
    if (e->rlen > 0) {
      size_t n = e->handler->flow(e, e->rbuf, e->rlen, out + total, max - total);
      size_t cons = e->consumed;
      if (cons > e->rlen) cons = e->rlen;
      if (cons) {
        memmove(e->rbuf, e->rbuf + cons, (e->rlen - cons) * sizeof(sox_sample_t));
        e->rlen -= cons;
      }
      total += n;
      if (n == 0 && cons == 0) {
        /* no progress: if input remains but output full, loop ends naturally */
        if (max - total == 0) break;
        if (e->rlen > 0 && !e->in_eof) {
          /* effect stalled with input available but produced nothing and
             consumed nothing; force more input by reading more? avoid loop */
          break;
        }
        if (e->in_eof && e->rlen == 0) continue;
        if (e->rlen > 0 && e->in_eof) {
          /* consume rest to avoid deadlock */
          e->rlen = 0;
        }
      }
    }
  }
  return total;
}

/* input callback for effects (unused in this engine) */

/* ============ pretty printing ============ */

const char * sox_pretty_size(double size, char * buf)
{
  if (size >= 1e9) sprintf(buf, "%.3gG", size / 1e9);
  else if (size >= 1e6) sprintf(buf, "%.3gM", size / 1e6);
  else if (size >= 1e3) sprintf(buf, "%.3gk", size / 1e3);
  else sprintf(buf, "%.0f", size);
  return buf;
}

