/* ============ main processing ============ */

static void print_file_info(sox_format_t * ft, const char * label);

static const char * encoding_name(sox_encoding_t e, unsigned bits)
{
  static char buf[64];
  switch (e) {
    case SOX_ENCODING_SIGN2: sprintf(buf, "%u-bit Signed Integer PCM", bits); break;
    case SOX_ENCODING_UNSIGNED: sprintf(buf, "%u-bit Unsigned Integer PCM", bits); break;
    case SOX_ENCODING_FLOAT: sprintf(buf, "%u-bit Floating Point PCM", bits); break;
    case SOX_ENCODING_ULAW: sprintf(buf, "%u-bit u-law", bits); break;
    case SOX_ENCODING_ALAW: sprintf(buf, "%u-bit A-law", bits); break;
    case SOX_ENCODING_IMA_ADPCM: sprintf(buf, "%u-bit IMA ADPCM", bits); break;
    case SOX_ENCODING_MS_ADPCM: sprintf(buf, "%u-bit MS ADPCM", bits); break;
    case SOX_ENCODING_GSM: sprintf(buf, "GSM"); break;
    default: sprintf(buf, "unknown"); break;
  }
  return buf;
}

/* duration string "00:00:00.10" */
static void fmt_duration(double secs, char * buf)
{
  int hours, mins;
  double s;
  if (secs < 0) secs = 0;
  hours = (int)(secs / 3600);
  mins = (int)((secs - hours * 3600) / 60);
  s = secs - hours * 3600 - mins * 60;
  sprintf(buf, "%02d:%02d:%05.2f", hours, mins, s);
}

static void print_file_info(sox_format_t * ft, const char * label)
{
  char dur[64], sz[64], br[64];
  double secs = 0;
  if (ft->signal.length && ft->signal.rate > 0 && ft->signal.channels)
    secs = (double)ft->signal.length / ft->signal.channels / ft->signal.rate;

  printf("\n%s File    : '%s'\n", label, ft->filename);
  printf("Channels       : %u\n", ft->signal.channels);
  printf("Sample Rate    : %g\n", ft->signal.rate);
  printf("Precision      : %u-bit\n", ft->signal.precision);
  if (ft->signal.length) {
    double sectors = ft->signal.channels ? (double)ft->signal.length / ft->signal.channels / 588.0 : 0;
    fmt_duration(secs, dur);
    printf("Duration       : %s = %llu samples = %g CDDA sectors\n", dur,
           (unsigned long long)(ft->signal.length / (ft->signal.channels ? ft->signal.channels : 1)),
           sectors);
  }
  if (ft->io_size)
    printf("File Size      : %s\n", sox_pretty_size((double)ft->io_size, sz));
  if (ft->io_size && secs > 0) {
    double bitrate = ft->io_size * 8.0 / secs;
    printf("Bit Rate       : %s\n", sox_pretty_size(bitrate, br));
  }
  printf("Sample Encoding: %s\n", encoding_name(ft->encoding.encoding, ft->encoding.bits));
}

